def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def max_prime_diff(arr):
    primes = [x for x in arr if is_prime(x)]
    if len(primes) < 2:
        return 0
    return max(abs(primes[i] - primes[j]) for i in range(len(primes)) for j in range(i + 1, len(primes)))
