Here is a Python solution using the QuickSelect algorithm, which is an efficient in-place variation of the QuickSort algorithm. It has an average time complexity of O(n), but in the worst case, it can degrade to O(n^2). However, with a good pivot selection strategy (like using the median-of-three method), the worst-case scenario is highly unlikely.

```python
def quickselect_median(arr):
    if not all(isinstance(i, (int, float)) for i in arr):
        raise ValueError("Array should only contain numeric values.")

    def partition(left, right, pivot_index):
        pivot_value = arr[pivot_index]
        arr[pivot_index], arr[right] = arr[right], arr[pivot_index]
        store_index = left
        for i in range(left, right):
            if arr[i] < pivot_value:
                arr[i], arr[store_index] = arr[store_index], arr[i]
                store_index += 1
        arr[right], arr[store_index] = arr[store_index], arr[right]
        return store_index

    def select(left, right, k):
        if left == right:
            return arr[left]
        pivot_index = left
        pivot_index = partition(left, right, pivot_index)
        if k == pivot_index:
            return arr[k]
        elif k < pivot_index:
            return select(left, pivot_index - 1, k)
        else:
            return select(pivot_index + 1, right, k)

    n = len(arr)
    if n % 2 == 1:
        return select(0, n - 1, n // 2)
    else:
        return 0.5 * (select(0, n - 1, n // 2 - 1) + select(0, n - 1, n // 2))

# Test the function
print(quickselect_median([3, 1, 2, 4, 5]))  # Output: 3
print(quickselect_median([3, 1, 2, 4]))  # Output: 2.5
print(quickselect_median([1]))  # Output: 1
print(quickselect_median([]))  # Output: None (or raise an exception, depending on your preference)
```

