    if not isinstance(lst, list):
        raise TypeError("Input must be a list")
    for item in lst:
        if not isinstance(item, (int, float)):
            raise TypeError("All elements in the list must be numbers")

    smallest_even = float('inf')
    second_smallest_even = float('inf')
    indices = []

    for i, num in enumerate(lst):
        if num % 2 == 0:  # Check if number is even
            if num < smallest_even:
                second_smallest_even = smallest_even
                smallest_even = num
                indices = [i]
            elif num < second_smallest_even and num != smallest_even:
                second_smallest_even = num
                indices = [i]
            elif num == smallest_even:
                indices.append(i)

    if second_smallest_even == float('inf'):
        return []
    else:
        return indices
