class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def insert_after(self, node, data):
        if not node:
            print("Error: Node does not exist.")
            return

        new_node = Node(data)
        new_node.prev = node
        node.next = new_node
        if node == self.tail:
