        if not self.head:
            print("Error: List is empty.")
            return

        if self.head == self.tail:
            self.head = None
            self.tail = None
        else:
            node = self.head
            while node.next != self.tail:
                node = node.next
            node.next = self.tail.next
            self.tail.next.prev = self.tail
            self.tail = node
            self.size -= 1

    def find_prev(self, data):
        current = self.head
        while current:
            if current.data == data:
                return current.prev
            current = current.next
        return None

    def find_next(self, data):
        current = self.head
        while current:
            if current.data == data:
                return current.next
            current = current.next
        return None

    def find_last(self):
        return self.tail

    def reverse(self):
        current = self.head
        while current:
            current.prev, current.next = current.next, current.prev
            current = current.prev
        self.head, self.tail = self.tail, self.head

    def sort(self):
        if self.size <= 1:
            return

        sorted_list = DoublyLinkedList()
        current = self.head
        while current:
            sorted_list.insert_after(sorted_list.head, current.data)
            current = current.next
        self.head, self.tail = sorted_list.head, sorted_list.tail

    def merge(self, other_list):
        if not self.head or not other_list.head:
            return

        if not self.head:
            self.head, self.tail = other_list.head, other_list.tail
        elif not other_list.head:
            self.tail.next = other_list.head
            other_list.head.prev = self.tail
            self.tail = other_list.tail
        else:
