def find_substring(string, substrings, case_sensitive=True, start=0, end=None, n=None):
    if not isinstance(string, str) or not isinstance(substrings, list):
        raise TypeError("Both 'string' and 'substrings' must be of type str and list respectively.")

    if end is None:
        end = len(string)

    if start < 0 or end > len(string) or start >= end:
        raise ValueError("Invalid start or end index.")

    results = []

    for substring in substrings:
        if not isinstance(substring, str):
            raise TypeError("All elements in 'substrings' must be of type str.")

        if not substring:
            results.append([])
            continue

        if not case_sensitive:
            string = string.lower()
            substring = substring.lower()

        substring_length = len(substring)
        if substring_length > len(string):
            results.append([])
            continue

        positions = []
        for i in range(start, end):
            if string[i:i+substring_length] == substring:
                positions.append(i)

        if n is not None:
            positions = positions[-n:]

        results.append(positions)

    return results
