def sqrt(n):
    if n < 2:
        return str(n)

    start, end = 1, n
    result = None

    while start <= end:
        mid = (start + end) // 2
        square = mid * mid

        if square == n:
            return str(mid)
        elif square < n:
            start = mid + 1
            result = mid
        else:
            end = mid - 1

    # Rounding to the nearest integer
    if result * result == n:
        return str(result)
    elif (result + 1) * (result + 1) <= n:
        return str(result + 1)
    else:
        return str(result)

# Test cases
