def are_anagrams(string1, string2):
    if not string1 or not string2:
        return False

    # Remove special characters and whitespace, and convert to lowercase
    string1 = ''.join(e for e in string1 if e.isalnum()).lower()
    string2 = ''.join(e for e in string2 if e.isalnum()).lower()

    # If the lengths are different after cleaning, they can't be anagrams
    if len(string1) != len(string2):
        return False

    # Create a dictionary to count the occurrences of each character in string1
    char_count = {}
    for char in string1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Subtract the count for each character in string2
    for char in string2:
        if char in char_count:
            char_count[char] -= 1
        else:
            # If a character in string2 is not in string1, they can't be anagrams
            return False

    # If all counts are zero, the strings are anagrams
    return all(value == 0 for value in char_count.values())
