Here's the Python code for the function `median_of_list` that calculates the median of a list of integers:

```python
def partition(lst, low, high):
    pivot = lst[high]
    i = low - 1
    for j in range(low, high):
        if lst[j] <= pivot:
            i += 1
            lst[i], lst[j] = lst[j], lst[i]
    lst[i + 1], lst[high] = lst[high], lst[i + 1]
    return i + 1

def quickselect(lst, low, high, k):
    if low == high:
        return lst[low]

    pivot_index = partition(lst, low, high)

    if k == pivot_index:
        return lst[k]
    elif k < pivot_index:
        return quickselect(lst, low, pivot_index - 1, k)
    else:
        return quickselect(lst, pivot_index + 1, high, k)

def median_of_list(lst):
    n = len(lst)
    if n % 2 == 1:
        return quickselect(lst, 0, n - 1, n // 2)
    else:
        return 0.5 * (quickselect(lst, 0, n - 1, n // 2 - 1) + quickselect(lst, 0, n - 1, n // 2))
