def group_and_sort(data, shared_key, sorting_key, remove_value):
    if not data:
        return {}

    groups = {}
    for d in data:
        if d[shared_key] not in groups:
            groups[d[shared_key]] = []
        groups[d[shared_key]].append(d)

    # Sorting groups based on the sum of the shared_key and the minimum of the sorting_key
    sorted_groups = sorted(groups.items(), key=lambda x: (-sum(d[shared_key] for d in x[1]), min(d[sorting_key] for d in x[1])))

    filtered_groups = {}
    for key, value in sorted_groups:
        filtered_groups[key] = [d for d in value if d.get(remove_value) != remove_value]

    return filtered_groups
```

