    mid = len(arr) // 2
    left = arr[:mid]
    right = arr[mid:]

    # Recursively sort the two halves
    left = optimized_sort(left)
    right = optimized_sort(right)

    # Merge the sorted halves without duplicates
    return merge_unique(left, right)

def merge_unique(left, right):
    merged = []
    i = 0
    j = 0

    # Compare and merge the elements from left and right halves
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            if not merged or left[i] != merged[-1]:
                merged.append(left[i])
            i += 1
        elif left[i] > right[j]:
            if not merged or right[j] != merged[-1]:
                merged.append(right[j])
            j += 1
        else:
            # Skip duplicates
            i += 1
            j += 1

    # Append the remaining elements
    while i < len(left):
        if not merged or left[i] != merged[-1]:
            merged.append(left[i])
        i += 1

    while j < len(right):
        if not merged or right[j] != merged[-1]:
            merged.append(right[j])
        j += 1

    return merged
```

This implementation uses the merge sort algorithm to sort the array in O(n log n) time complexity. The `merge_unique` function ensures that no duplicates are added to the merged array by checking if the last element in the merged array is the same as the current element before appending it. This results in a space complexity of O(1) since we are not using any additional data structures that scale with the input size.

