```python
class GroceryInventory:
    def __init__(self):
        self.inventory = {}  # Hash map to store items by name
        self.item_list = []  # List to maintain order of items

    def add_item(self, name, quantity, price, nutritional_info):
        if not (1 <= quantity <= 1000) or not (0.01 <= price <= 1000):
            raise ValueError("Invalid quantity or price")
        if not isinstance(nutritional_info, dict) or \
           'calories' not in nutritional_info or \
           'carbohydrates' not in nutritional_info or \
           not isinstance(nutritional_info['calories'], int) or \
           not isinstance(nutritional_info['carbohydrates'], float):
            raise ValueError("Invalid nutritional information")

        item = {
            'name': name,
            'quantity': quantity,
            'price': price,
            'nutritional_info': nutritional_info
        }
        self.inventory[name] = item
        self.item_list.append(name)

    def remove_item(self, name):
        if name not in self.inventory:
            raise ValueError("Item not found")
        removed_item = self.inventory.pop(name)
        self.item_list.remove(name)

    def update_quantity(self, name, new_quantity):
        if not (1 <= new_quantity <= 1000):
            raise ValueError("Invalid quantity")
        if name not in self.inventory:
            raise ValueError("Item not found")
        self.inventory[name]['quantity'] = new_quantity

    def update_price(self, name, new_price):
        if not (0.01 <= new_price <= 1000):
            raise ValueError("Invalid price")
        if name not in self.inventory:
            raise ValueError("Item not found")
        self.inventory[name]['price'] = new_price

    def get_nutritional_info(self, name):
        if name not in self.inventory:
            raise ValueError("Item not found")
        return self.inventory[name]['nutritional_info']
