```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None
        self.prev = None

class CircularDoublyLinkedList:
    def __init__(self):
        self.head = None

    def insert_at_beginning(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            new_node.next = new_node
            new_node.prev = new_node
        else:
            new_node.next = self.head
            new_node.prev = self.head.prev
            self.head.prev.next = new_node
            self.head.prev = new_node

    def insert_at_end(self, data):
        new_node = Node(data)
        if self.head is None:
            self.head = new_node
            new_node.next = new_node
            new_node.prev = new_node
        else:
            new_node.next = self.head
            new_node.prev = self.head.prev
            self.head.prev.next = new_node
            self.head.prev = new_node

    def delete_node(self, node):
        if node is None:
            return False
        if node.prev:
            node.prev.next = node.next
            node.next.prev = node.prev
        else:
            self.head = node.next
            self.head.prev = self.head
        node.next = None
        node.prev = None
        return True

    def get_length(self):
        if self.head is None:
            return 0
        count = 1
        current = self.head.next
        while current != self.head:
            count += 1
            current = current.next
        return count

    def traverse_forward(self):
        if self.head is None:
            return []
        result = []
        current = self.head
        while True:
            result.append(current.data)
            current = current.next
            if current == self.head:
                break
        return result

    def traverse_backward(self):
        if self.head is None:
            return []
        result = []
        current = self.head.prev
        while True:
            result.append(current.data)
            current = current.prev
            if current == self.head.prev:
                break
        return result[::-1]

    def insert_at_position(self, position, data):
        if position < 0:
            return "Error: Position must be non-negative."
        if position == 0:
            self.insert_at_beginning(data)
            return
        new_node = Node(data)
        current = self.head
        index = 0
        while current and index < position - 1:
            current = current.next
            index += 1
        if current is None:
            return "Error: Position out of range."
        new_node.next = current
        new_node.prev = current.prev
        current.prev.next = new_node
        current.prev = new_node

    def get_nth_node_from_beginning(self, n):
        if n < 0:
            return "Error: Position must be non-negative."
        if self.head is None:
            return None
        current = self.head
        for _ in range(n):
            if current is None:
                return None
            current = current.next
            if current == self.head:
                break
        return current

    def get_nth_node_from_end(self, n):
        if n < 0:
            return "Error: Position must be non-negative."
        if self.head is None:
            return None
        current = self.head
        length = self.get_length()
        for _ in range(length - n):
            if current is None:
                return None
            current = current.next
        return current

    def reverse(self):
        if self.head is None:
            return
        current = self.head
        while True:
            temp = current.next
            current.next = current.prev
            current.prev = temp
            if current == self.head:
                break
            current = current.prev
        if temp is not None:
            self.head = temp.prev

    def __str__(self):
        if self.head is None:
            return "Empty list"
        result = []
        current = self.head
        while True:
            result.append(str(current.data))
            current = current.next
            if current == self.head:
                break
        return " -> ".join(result)
