def count_unique_vowels(sentence):
    vowels = set('aeiou')
    unique_vowels = set()
    prev_consonant = False

    for char in sentence:
        if char.lower() in vowels:
            if prev_consonant:
                unique_vowels.add(char.lower())
            prev_consonant = False
        elif char.lower() not in vowels:
            prev_consonant = True

    return len(unique_vowels)

