    s = ''.join(c for c in s if c.isalpha())  # Remove symbols
    s = ''.join(c for i, c in enumerate(s) if i % 2 == 0 or c.lower() not in vowels)  # Alternating case
    s = ''.join(sorted(s))  # Sort lexicographically
    s = s[:len(s) - len(s) % 3]  # Make length divisible by 3
    return s

def count_vowels(s):
    return sum(1 for c in s if c in 'aeiouAEIOU')

def find_valid_string(s):
    valid_strings = []
    for i in range(0, len(s), 3):
        valid_strings.append(s[i:i+3])

    if not valid_strings:
        return ""

    valid_strings = [s for s in valid_strings if any(c in vowels for c in s)]

    if not valid_strings:
        return ""

    valid_strings = sorted(valid_strings, key=lambda x: (-count_vowels(x), len(x), x))

    return valid_strings[0]

def solution(s):
    s = remove_symbols(s)
    return find_valid_string(s)
```

