class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

    def __repr__(self):
        return f"Person(name='{self.name}', age={self.age})"

def merge_sort(arr, descending=False):
    if len(arr) <= 1:
        return arr

    mid = len(arr) // 2
    left = merge_sort(arr[:mid], descending)
    right = merge_sort(arr[mid:], descending)

    return merge(left, right, descending)

def merge(left, right, descending):
    result = []
    i = j = 0

    while i < len(left) and j < len(right):
        if (not descending and left[i].name < right[j].name) or (descending and left[i].name > right[j].name):
            result.append(left[i])
            i += 1
        elif (not descending and left[i].name > right[j].name) or (descending and left[i].name < right[j].name):
            result.append(right[j])
            j += 1
        else:
            if not descending and left[i].age <= right[j].age:
                result.append(left[i])
                i += 1
            elif descending and left[i].age >= right[j].age:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1

    result.extend(left[i:])
    result.extend(right[j:])
    return result

