    for word in words:
        length = 0
        for char in word:
            if char.isalpha():
                length += 1
        if length > max_length:
            max_length = length

    # Remove all words with the longest length
    result = ""
    for word in words:
        length = 0
        for char in word:
            if char.isalpha():
                length += 1
        if length != max_length:
            result += word + " "

    return result.strip()
