def merge_sort(arr):
    if len(arr) <= 1:
        return arr

    mid = len(arr) // 2
    left = merge_sort(arr[:mid])
    right = merge_sort(arr[mid:])

    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0

    while i < len(left) and j < len(right):
        # Ignore non-alphabetic characters
        left_ascii_sum = sum(ord(c) for c in left[i] if c.isalpha())
        right_ascii_sum = sum(ord(c) for c in right[j] if c.isalpha())

        if left_ascii_sum > right_ascii_sum:
            result.append(left[i])
            i += 1
        elif left_ascii_sum < right_ascii_sum:
            result.append(right[j])
            j += 1
        else:
            # In case of a tie, sort lexicographically
            if left[i] < right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1

    result.extend(left[i:])
    result.extend(right[j:])

    return result

