            raise ValueError("Street, city, state, and zip code cannot be empty.")
        if not re.match("^[a-zA-Z\s]+$", street) or not re.match("^[a-zA-Z\s]+$", city) or not re.match("^[a-zA-Z\s]+$", state):
            raise ValueError("Street, city, and state cannot contain numbers or special characters.")
        if len(street) > 50 or len(city) > 50 or len(state) > 50:
            raise ValueError("Street, city, and state cannot exceed 50 characters.")
        if not re.match("^\d+$", house_number) or len(house_number) != 1 or house_number[0] not in ['1', '2', '3', '4', '5', '6', '7', '8', '9']:
            raise ValueError("House number must be a single digit from 1 to 9.")
        if len(zip_code) != 5 or not zip_code.isdigit():
            raise ValueError("Zip code must be a 5-digit number.")

    def add_address(self, street, house_number, city, state, zip_code):
        self.validate_address(street, house_number, city, state, zip_code)
        self.addresses.append({
            'street': street,
            'house_number': house_number,
            'city': city,
            'state': state,
            'zip_code': zip_code
        })

    def remove_address(self, address_id):
        if address_id < len(self.addresses):
            del self.addresses[address_id]
        else:
            raise ValueError("Invalid address ID.")

    def get_address(self, address_id):
        if address_id < len(self.addresses):
            return self.addresses[address_id]
        else:
            raise ValueError("Invalid address ID.")

    def calculate_age_in_months(self):
        today = datetime.today()
        birth_date = today.replace(year=self.age - 1)
        return (today - birth_date).days // 30

    def validate_age_in_months(self, age_in_months):
        if isinstance(age_in_months, int) and age_in_months > 0:
            return age_in_months
        else:
            raise ValueError("Age in months must be a positive integer.")

    def calculate_birth_year(self):
        return self.age - 1

    def validate_birth_year(self, birth_year):
        if isinstance(birth_year, int) and 1900 <= birth_year <= 2020:
            return birth_year
        else:
            raise ValueError("Birth year must be a 4-digit number between 1900 and 2020.")

    def validate_zip_code(self, zip_code):
        if len(zip_code) == 5 and zip_code.isdigit():
            return zip_code
        else:
            raise ValueError("Invalid zip code format.")

    def validate_full_address(self, address):
        if len(address) > 100:
            raise ValueError("Full address cannot exceed 100 characters.")
        if not re.match("^[a-zA-Z\s,]+$", address):
            raise ValueError("Full address cannot contain numbers or special characters other than commas.")

    def display_data(self):
        print(f"Name: {self.name}")
        print(f"Age: {self.age} years")
        print(f"Hobbies: {', '.join(self.hobbies)}")
        for i, address in enumerate(self.addresses):
            print(f"Address {i+1}:")
            print(f"Street: {address['street']}")
            print(f"House Number: {address['house_number']}")
            print(f"City: {address['city']}")
            print(f"State: {address['state']}")
            print(f"Zip Code: {address['zip_code']}")

    def search_hobby(self, hobby):
        return hobby.lower() in [h.lower() for h in self.hobbies]
