def remove_vowels(s):
    # Base case: if the string is empty, return an empty string
    if len(s) == 0:
        return ""
    # Recursive case: check the first character
    else:
        # If the first character is a vowel, skip it and call the function recursively on the rest of the string
        if s[0].lower() in 'aeiou':
            return remove_vowels(s[1:])
        # If the first character is not a vowel, add it to the result of the recursive call on the rest of the string
        else:
            return s[0] + remove_vowels(s[1:])

# Test cases
print(remove_vowels("Hello World"))  # Output: "Hll Wrld"
print(remove_vowels("AI is Fun"))    # Output: "H s Fn"
print(remove_vowels("aeiou"))        # Output: ""
print(remove_vowels(""))             # Output: ""
print(remove_vowels("BCDFG"))        # Output: "BCDFG"
```

