```python
def group_students(student_list):
    if not isinstance(student_list, list):
        raise ValueError("Input should be a list of student objects.")

    result = {}
    for student in student_list:
        if not hasattr(student, 'name') or not hasattr(student, 'major') or not hasattr(student, 'GPA'):
            continue
        if student.GPA < 3.0:
            continue
        if student.major not in result:
            result[student.major] = []
        result[student.major].append(student.name)

    # Sorting the names in each major's list
    for major in result:
        result[major].sort()

    # Removing majors with no students
    result = {major: names for major, names in result.items() if names}

    return result
```

