def multiply_matrices(matrix1, matrix2):
    # Check if either matrix is empty
    if not matrix1 or not matrix2:
        return []

    # Check if matrices are valid (all rows have the same number of columns)
    if not all(len(row) == len(matrix1[0]) for row in matrix1) or not all(len(row) == len(matrix2[0]) for row in matrix2):
        raise Exception("Invalid matrix: All rows must have the same number of columns.")

    # Check if matrices have compatible dimensions
    if len(matrix1[0]) != len(matrix2):
        raise Exception("Incompatible dimensions: Number of columns in the first matrix must be equal to the number of rows in the second matrix.")

    # Check if matrices contain elements of the same data type
