To find the median of a sorted array in less than log(n) time, we can use a modified version of the binary search algorithm. This approach works by partitioning the array around a pivot and then determining the position of the median based on the number of elements on either side of the pivot.

Here's a Python implementation of the algorithm:

```python
def find_median_sorted_array(arr):
    def partition(left, right, pivot_index):
        pivot = arr[pivot_index]
        arr[pivot_index], arr[right] = arr[right], arr[pivot_index]
        store_index = left
        for i in range(left, right):
            if arr[i] < pivot:
                arr[i], arr[store_index] = arr[store_index], arr[i]
                store_index += 1
        arr[right], arr[store_index] = arr[store_index], arr[right]
        return store_index

    def select(left, right, k):
        if left == right:
            return arr[left]
        pivot_index = left
        pivot_index = partition(left, right, pivot_index)
        if k == pivot_index:
            return arr[k]
        elif k < pivot_index:
            return select(left, pivot_index - 1, k)
        else:
            return select(pivot_index + 1, right, k)

    n = len(arr)
    if n % 2 == 1:
        return select(0, n - 1, n // 2)
    else:
        return 0.5 * (select(0, n - 1, n // 2 - 1) + select(0, n - 1, n // 2))

# Test the function
arr = [1, 2, 2, 3, 4, 5, 6, 7, 8]
print(find_median_sorted_array(arr))  # Output: 4.5
```

