import csv
import collections
import operator

def task_func(csv_file_path):
    try:
        with open(csv_file_path, newline='') as csvfile:
            reader = csv.DictReader(csvfile)
            sales_data = collections.defaultdict(int)

            for row in reader:
                try:
                    product = row['product']
                    quantity = int(row['quantity'])
                    sales_data[product] += quantity
                except (ValueError, KeyError) as e:
                    raise ValueError(f"Invalid data format in row: {row}. Error: {e}")

        if not sales_data:
            raise ValueError("No valid sales data found in the CSV file.")

        best_selling_product = max(sales_data.items(), key=operator.itemgetter(1))[0]
        return best_selling_product

    except FileNotFoundError:
        raise FileNotFoundError(f"The file at {csv_file_path} was not found.")
    except Exception as e:
        raise RuntimeError(f"An error occurred while processing the CSV file: {e}")
