```python
import pandas as pd
import numpy as np
import itertools
from datetime import datetime, timedelta
import seaborn as sns

def task_func(df, fruits=None, days=None, seed=None, sales_lower_bound=1, sales_upper_bound=50):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("The input 'df' must be a pandas DataFrame.")

    if df.empty:
        raise ValueError("The input DataFrame 'df' cannot be empty.")

    if sales_lower_bound >= sales_upper_bound:
        raise ValueError("The 'sales_lower_bound' must be less than 'sales_upper_bound'.")

    if fruits is None:
        fruits = ['Apple', 'Banana', 'Cherry', 'Date', 'Elderberry']
    if days is None:
        days = range(7)

    if seed is not None:
        np.random.seed(seed)

    date_range = [datetime.now() + timedelta(days=i) for i in days]
    fruit_iter = itertools.cycle(fruits)

    for date in date_range:
        for _ in range(len(fruits)):
            fruit = next(fruit_iter)
            sales = np.random.randint(sales_lower_bound, sales_upper_bound + 1)
            df = df.append({
                'Date': date,
                'Fruit': fruit,
                'Sales': sales
            }, ignore_index=True)

    sns.set(style="whitegrid")
    plot = sns.boxplot(x='Fruit', y='Sales', data=df)
    plot.set_title('Sales Distribution by Fruit')

    return df, plot
