import zipfile
import io
from django.http import FileResponse, HttpRequest
from django.conf import settings

def task_func(request, file_paths):
    if not file_paths:
        return FileResponse(content=b'No files to download', status=404)

    zip_buffer = io.BytesIO()
    with zipfile.ZipFile(zip_buffer, 'w') as zip_file:
        for file_path in file_paths:
            if not os.path.exists(file_path) or not os.path.isfile(file_path):
                return FileResponse(content=b'One or more files do not exist', status=404)
            zip_file.write(file_path, os.path.basename(file_path))

    zip_buffer.seek(0)
    response = FileResponse(zip_buffer, as_attachment=True, filename='downloaded_files.zip')
    response['Content-Disposition'] = f'attachment; filename="downloaded_files.zip"'

    return response
