    submit = SubmitField('Log In')

login_manager = LoginManager()

def task_func(secret_key, template_folder):
    app = Flask(__name__, instance_relative_config=True, static_folder='static', template_folder=template_folder)
    app.config.from_pyfile('config.py', silent=True)

    @login_manager.user_loader
    def load_user(user_id):
        # In a real application, you'd fetch the user from a database.
        # Here, we just return a mock user for demonstration.
        return User(user_id, 'testuser', generate_password_hash('testpassword'))

    @app.route('/login', methods=['GET', 'POST'])
    def login():
        form = LoginForm()
        if form.validate_on_submit():
            user = load_user(form.username.data)
            if check_password_hash(user.password_hash, form.password.data):
                login_user(user)
                return redirect(url_for('protected'))
            else:
                flash('Invalid username or password', 'danger')
        return render_template('login.html', form=form)

    @app.route('/logout')
    @login_required
    def logout():
        logout_user()
        return redirect(url_for('login'))

    @app.route('/protected')
    @login_required
    def protected():
        return render_template('protected.html')

