import csv
from collections import Counter
import operator

def task_func(csv_file, csv_delimiter):
    if not isinstance(csv_delimiter, str) or len(csv_delimiter) != 1:
        raise ValueError("Delimiter must be a single character.")

    word_count = Counter()

    try:
        with open(csv_file, 'r', newline='', encoding='utf-8') as file:
            reader = csv.reader(file, delimiter=csv_delimiter)
            for row in reader:
                for word in row:
                    word_count[word.lower()] += 1
    except FileNotFoundError:
        raise FileNotFoundError(f"The file {csv_file} does not exist.")

    # Sort the words by their frequency in descending order
    sorted_word_count = sorted(word_count.items(), key=operator.itemgetter(1), reverse=True)

    return sorted_word_count
