import subprocess
from ipaddress import IPv4Network

def task_func(ip_range):
    # Validate the IP range
    try:
        network = IPv4Network(ip_range)
    except ValueError:
        raise ValueError("Invalid IP address range")

    # Initialize the result dictionary
    active_ips = {}

    # Iterate over each IP in the range
    for ip in network.hosts():
        try:
            # Execute the ping command
            result = subprocess.run(['ping', '-c', '1', str(ip)], 
                                     stdout=subprocess.PIPE, 
                                     stderr=subprocess.PIPE, 
                                     universal_newlines=True)

            # Check if the ping was successful
            if result.returncode == 0:
                active_ips[str(ip)] = True
            else:
                active_ips[str(ip)] = False
        except subprocess.CalledProcessError as e:
            # If ping fails, record it as inactive
            active_ips[str(ip)] = False
            print(f"Ping to {ip} failed with error: {e.stderr}")

    return active_ips
