import pandas as pd
from sklearn.preprocessing import LabelEncoder
def task_func(data):
    if not isinstance(data, pd.DataFrame):
        return "Error: Input must be a pandas DataFrame."

    if data.empty:
        return "Error: Input DataFrame is empty."

    categorical_columns = data.select_dtypes(include=['object', 'category']).columns

    if categorical_columns.empty:
        return "Error: No categorical columns found in the DataFrame."

    encoder = LabelEncoder()
    encoded_data = {}

    for column in categorical_columns:
        try:
            encoded_values = encoder.fit_transform(data[column])
            encoded_data[column] = list(zip(data[column], encoded_values))
        except Exception as e:
            return f"Error encoding column '{column}': {str(e)}"

    result_df = pd.DataFrame(encoded_data, columns=['Category', 'Encoded'])
    return result_df
