        raise ValueError("Weather conditions must be valid entries from the provided list.")

    if not all(timezone in pytz.all_timezones for timezone in timezones.values()):
        raise ValueError("All timezones must be valid pytz timezones.")

    set_seed(seed)

    weather_data = []
