import numpy as np
from scipy import stats
# Constants
FEATURES = ['feature1', 'feature2', 'feature3', 'feature4', 'feature5']
def task_func(df, dct):
    if df.empty:
        return 'Invalid input: DataFrame is empty.'

    if 'feature1' not in df.columns:
        return 'Invalid input: DataFrame does not contain "feature1".'

    if not all(feature in dct for feature in FEATURES):
        return 'Invalid input: Mapping dictionary does not contain mappings for all features in FEATURES.'

    for feature in FEATURES:
        if not np.issubdtype(df[feature].dtype, np.number):
            return f'Invalid input: Feature "{feature}" contains non-numeric data.'

    for feature, value in dct.items():
        if feature in df.columns:
            df.loc[df[feature] == value, feature] = np.nan

    for feature in FEATURES:
        if df[feature].isnull().all():
            return f'Invalid input: All values for feature "{feature}" are null after replacements.'

    stats_dict = {}
    for feature in FEATURES:
        data = df[feature].dropna()

        if data.empty:
            stats_dict[feature] = 'Invalid input: No valid data for feature after replacements.'
            continue

        stats_dict[feature] = {
            'mean': np.mean(data),
            'median': np.median(data),
            'mode': stats.mode(data)[0][0],
            'variance': np.var(data, ddof=1)  # Sample variance
        }

    return stats_dict
