import numpy as np
import itertools
import json

def task_func(data_list, json_file_name="mean_values.json"):
    if not data_list:
        return "The input data list is empty."

    # Extract numeric values from the data list
    numeric_values = [x for x in data_list if isinstance(x, (int, float))]

    if not numeric_values:
        return {}

    # Calculate means for each position
    means = {}
    for position, values in itertools.groupby(numeric_values, key=lambda x: x // len(numeric_values)):
        means[f'Position {position}'] = np.mean(list(values))

    # Export results to JSON file if specified
    if json_file_name:
        with open(json_file_name, 'w') as json_file:
            json.dump(means, json_file, indent=4)

    return means
