import os
import glob
import shutil
import time
# Constants
FILE_EXTENSIONS = ['.txt', '.csv', '.xlsx', '.docx', '.pdf']

def task_func(my_path: str, days_old: int) -> str:
    if not os.path.exists(my_path):
        raise FileNotFoundError(f"The directory {my_path} does not exist.")

    archive_dir = os.path.join(my_path, 'archive')

    if not os.access(my_path, os.W_OK):
        raise PermissionError(f"No write permissions in the directory {my_path}.")

    if not os.path.exists(archive_dir):
        os.makedirs(archive_dir)

    current_time = time.time()
    threshold_time = current_time - (days_old * 24 * 60 * 60)

    for ext in FILE_EXTENSIONS:
        file_paths = glob.glob(os.path.join(my_path, f'*.{ext}'))
        for file_path in file_paths:
            if os.path.getmtime(file_path) < threshold_time:
                try:
                    shutil.move(file_path, archive_dir)
                except OSError as e:
                    print(f"Error moving file {file_path}: {e}")

    return archive_dir
```

