                if not text:
                    continue
                subdir = text
                if not os.path.exists(os.path.join(directory, subdir)):
                    os.makedirs(os.path.join(directory, subdir))
                shutil.move(file_path, os.path.join(directory, subdir, filename))
                if subdir not in file_dict:
                    file_dict[subdir] = []
                file_dict[subdir].append(filename)

