import re
import os
import glob
from pathlib import Path

def task_func(pattern, directory, extensions):
    if not os.path.exists(directory):
        raise FileNotFoundError(f"The directory {directory} does not exist.")

    pattern_compiled = re.compile(pattern, re.IGNORECASE)
    matching_files = []

    for ext in extensions:
        file_paths = glob.glob(os.path.join(directory, f"*.{ext}"))
        for file_path in file_paths:
            if not Path(file_path).is_file():
                continue  # Skip if it's not a file

            with open(file_path, 'r', encoding='utf-8', errors='ignore') as file:
                for line in file:
                    if pattern_compiled.search(line):
                        matching_files.append(file_path)
                        break  # No need to check further lines in this file

    return matching_files
