Here's a high-level design for the search API using Python and Flask, along with Elasticsearch for searching. This example assumes you have Elasticsearch installed and running, and you're using Flask-JWT-Extended for authentication.

First, let's define the `SignalDocument` and `StatusMessagesSearch` classes:

```python
from datetime import datetime

class SignalDocument:
    def __init__(self, id, name, location, created_at):
        self.id = id
        self.name = name
        self.location = location
        self.created_at = created_at

class StatusMessagesSearch:
    def __init__(self, id, signal_id, state, active, message, created_at):
        self.id = id
        self.signal_id = signal_id
        self.state = state
        self.active = active
        self.message = message
        self.created_at = created_at
```

Now, let's create the Flask application and the views:

```python
from flask import Flask, request, jsonify
from flask_jwt_extended import JWTManager, jwt_required, get_jwt_identity
from elasticsearch import Elasticsearch
from elasticsearch.exceptions import ConnectionError

app = Flask(__name__)
app.config['JWT_SECRET_KEY'] = 'super-secret'  # Change this!
jwt = JWTManager(app)
es = Elasticsearch()

@app.route('/search-signals', methods=['GET'])
@jwt_required()
def search_signals():
    try:
        search_term = request.args.get('search_term', '')
        sort_field = 'created_at'
        page = int(request.args.get('page', 1))
        per_page = int(request.args.get('per_page', 10))

        query = {
            "query": {
                "multi_match": {
                    "query": search_term,
                    "fields": ["name", "location"]
                }
            },
            "sort": [sort_field],
            "from": (page - 1) * per_page,
            "size": per_page
        }

        response = es.search(index='signals', body=query)
        return jsonify([hit['_source'] for hit in response['hits']['hits']])

    except ConnectionError:
        return jsonify({"error": "Elasticsearch service is unavailable"}), 503

@app.route('/search-status-messages', methods=['GET'])
@jwt_required()
def search_status_messages():
    try:
        search_term = request.args.get('search_term', '')
        state = request.args.get('state', '')
        active = request.args.get('active', '')
        page = int(request.args.get('page', 1))
        per_page = int(request.args.get('per_page', 10))

        query = {
            "query": {
                "bool": {
                    "must": [
                        {"match": {"message": search_term}}
                    ],
                    "filter": [
                        {"term": {"state": state}},
                        {"term": {"active": active == 'true'}}
                    ]
                }
            },
            "sort": [{"created_at": {"order": "desc"}}],
            "from": (page - 1) * per_page,
            "size": per_page
        }

        response = es.search(index='status_messages', body=query)
        return jsonify([hit['_source'] for hit in response['hits']['hits']])

    except ConnectionError:
        return jsonify({"error": "Elasticsearch service is unavailable"}), 503

if __name__ == '__main__':
    app.run(debug=True)
```

