To design the system, we'll use Python and create a class `Tender` to represent a tender with its attributes and methods for transitioning statuses. We'll also create a `Lot` class to handle tenders with multiple lots. For logging, we'll use Python's built-in `logging` module.

```python
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class Tender:
    def __init__(self, tender_id, tender_type, bids=None, complaints=None, auction_result=None):
        self.tender_id = tender_id
        self.tender_type = tender_type
        self.bids = bids if bids is not None else 0
        self.complaints = complaints if complaints is not None else []
        self.auction_result = auction_result
        self.status = 'draft'
        self.auction_period = None

    def transition_status(self):
        if self.bids == 0:
            self.status = 'unsuccessful'
            self.auction_period = 0
        elif self.bids >= 1:
            if self.tender_type == 'below-threshold':
                self.status = 'qualification'
            elif self.tender_type in ['open_ua', 'open_ua_defense']:
                if len(self.complaints) > 0:
                    self.status = 'complaint'
                else:
                    self.status = 'qualification'
            if self.status == 'qualification':
                self.auction_period = self.set_auction_period()
        return self.status

    def set_auction_period(self):
        # Implement specific rules for setting auction period based on tender type
        if self.tender_type == 'below-threshold':
            return 7
        elif self.tender_type in ['open_ua', 'open_ua_defense']:
            return 14
        return 0

    def handle_complaint(self, complaint):
        self.complaints.append(complaint)
        self.transition_status()

    def transition_to_auction(self):
        if self.status == 'qualification':
            self.status = 'auction'
            self.auction_period = self.set_auction_period()

class Lot(Tender):
    def __init__(self, lot_id, tender, bids=None, complaints=None, auction_result=None):
        super().__init__(tender_id=f'{tender.tender_id}_{lot_id}', tender_type=tender.tender_type, bids=bids, complaints=complaints, auction_result=auction_result)
        self.tender = tender

    def transition_status(self):
        super().transition_status()
        if self.status == 'qualification':
            self.tender.transition_to_auction()

# Unit tests
import unittest

class TestTenderTransitions(unittest.TestCase):
    def setUp(self):
        self.below_threshold_tender = Tender(tender_id='BT1', tender_type='below-threshold')
        self.open_ua_tender = Tender(tender_id='OU1', tender_type='open_ua')
        self.open_ua_defense_tender = Tender(tender_id='OUD1', tender_type='open_ua_defense')
        self.lot_tender = Lot(lot_id='L1', tender=self.open_ua_tender)

    def test_no_bids_unsuccessful(self):
        self.below_threshold_tender.bids = 0
        self.assertEqual(self.below_threshold_tender.transition_status(), 'unsuccessful')

    def test_one_bid_qualification(self):
        self.below_threshold_tender.bids = 1
        self.assertEqual(self.below_threshold_tender.transition_status(), 'qualification')

    def test_open_ua_one_bid_qualification(self):
        self.open_ua_tender.bids = 1
        self.assertEqual(self.open_ua_tender.transition_status(), 'qualification')

    def test_open_ua_defense_one_bid_qualification(self):
        self.open_ua_defense_tender.bids = 1
        self.assertEqual(self.open_ua_defense_tender.transition_status(), 'qualification')

    def test_open_ua_one_complaint_complaint(self):
        self.open_ua_tender.handle_complaint('Complaint 1')
        self.assertEqual(self.open_ua_tender.transition_status(), 'complaint')

    def test_open_ua_defense_one_complaint_complaint(self):
        self.open_ua_defense_tender.handle_complaint('Complaint 1')
        self.assertEqual(self.open_ua_defense_tender.transition_status(), 'complaint')

    def test_lot_transition_to_auction(self):
        self.lot_tender.bids = 1
        self.lot_tender.transition_status()
        self.assertEqual(self.lot_tender.status, 'qualification')
        self.assertEqual(self.open_ua_tender.status, 'auction')

if __name__ == '__main__':
    unittest.main()
```

