import socket
import threading
import pickle
import random
import os

class Player:
    def __init__(self, player_id, name, skin):
        self.player_id = player_id
        self.name = name
        self.skin = skin
        self.x = 0
        self.y = 0
        self.color = self.generate_color()

    def generate_color(self):
        while True:
            r, g, b = random.randint(0, 255), random.randint(0, 255), random.randint(0, 255)
            if r + g + b < 720:
                return (r, g, b)

class GameServer:
    def __init__(self, host='localhost', port=8080):
        self.host = host
        self.port = port
        self.server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server.bind((host, port))
        self.server.listen(100)
        self.players = {}
        self.load_config()

    def load_config(self):
        config_file = 'server.config'
        if os.path.exists(config_file):
            with open(config_file, 'r') as f:
                content = f.read().strip()
                if content.startswith('host: ') and content.endswith('port: '):
                    self.host = content.split('host: ')[1].split('port: ')[0].strip()
                    self.port = int(content.split('port: ')[1].strip())
        print(f"Using server configuration: {self.host}:{self.port}")

    def handle_client(self, client_socket):
        while True:
            try:
                data = client_socket.recv(1024)
                if not data:
                    break
                command = pickle.loads(data)
                if command['type'] == 'move':
                    self.move_player(command['data'])
                elif command['type'] == 'id':
                    self.send_player_id(client_socket)
                elif command['type'] == 'get':
                    self.send_game_state(client_socket)
            except Exception as e:
                print(f"Error handling client: {e}")
                break
        self.remove_player(client_socket)
        client_socket.close()

    def move_player(self, data):
        player_id = data['id']
        x, y = data['x'], data['y']
        if player_id in self.players:
            self.players[player_id].x, self.players[player_id].y = x, y

    def send_player_id(self, client_socket):
        player_id = list(self.players.keys())[0]  # For simplicity, we assume only one player
        client_socket.send(pickle.dumps({'type': 'id', 'data': {'id': player_id}}))

    def send_game_state(self, client_socket):
        client_socket.send(pickle.dumps({'type': 'get', 'data': self.players}))

    def remove_player(self, client_socket):
        player_id = list(self.players.keys())[0]  # For simplicity, we assume only one player
        del self.players[player_id]

    def start(self):
        print("Game server started on", self.host, self.port)
        while True:
            client_socket, addr = self.server.accept()
            print(f"Accepted connection from {addr}")
            client_thread = threading.Thread(target=self.handle_client, args=(client_socket,))
            client_thread.start()

if __name__ == "__main__":
    game_server = GameServer()
    game_server.start()
