class QueueDelta:
    @staticmethod
    def calculate(old_queues: List[Queue], new_queues: List[Queue]) -> Dict[str, List[Queue]]:
        if not isinstance(old_queues, list) or not isinstance(new_queues, list):
            raise ValueError("Both old_queues and new_queues must be lists.")

        added = [q for q in new_queues if q not in old_queues]
        removed = [q for q in old_queues if q not in new_queues]
        penalty_updated = [q for q in new_queues if q in old_queues and q.penalty != old_queues[new_queues.index(q)].penalty]

        return {
