def string_operations(s, operations):
    def slice_operation(start, end):
        try:
            return s[start:end]
        except IndexError:
            return ""

    def check_operation(sub):
        return sub in s

    def concat_operation(str_to_add):
        return s + str_to_add

    def format_operation(values):
        if len(values) != s.count('{}'):
            raise ValueError("The number of placeholders in the string does not match the number of values provided.")
        return s.format(*values)

    results = []
    for operation in operations:
        op_name, *params = operation
        if op_name == "slice":
            results.append(slice_operation(*params))
        elif op_name == "check":
            results.append(check_operation(params[0]))
        elif op_name == "concat":
            results.append(concat_operation(params[0]))
        elif op_name == "format":
            results.append(format_operation(params))
        else:
            raise ValueError(f"Unsupported operation: {op_name}")

    return results

# Unit tests
