```python
import pygame
import sys
import random

# Constants
WIDTH, HEIGHT = 600, 600
CELL_SIZE = 10
GRID_ROWS, GRID_COLS = WIDTH // CELL_SIZE, HEIGHT // CELL_SIZE

# Colors
WHITE = (255, 255, 255)
BLACK = (0, 0, 0)

# Initialize Pygame
pygame.init()
screen = pygame.display.set_mode((WIDTH, HEIGHT))
pygame.display.set_caption("Conway's Game of Life")
clock = pygame.time.Clock()

# Grid initialization
grid = [[0 for _ in range(GRID_COLS)] for _ in range(GRID_ROWS)]

def draw_grid():
    for row in range(GRID_ROWS):
        for col in range(GRID_COLS):
            pygame.draw.rect(screen, WHITE if grid[row][col] else BLACK, (col * CELL_SIZE, row * CELL_SIZE, CELL_SIZE, CELL_SIZE))

def get_neighbors(row, col):
    neighbors = 0
    for r in range(max(0, row - 1), min(GRID_ROWS, row + 2)):
        for c in range(max(0, col - 1), min(GRID_COLS, col + 2)):
            if (r, c) != (row, col):
                neighbors += grid[r][c]
    return neighbors

def update_grid():
    new_grid = [[0 for _ in range(GRID_COLS)] for _ in range(GRID_ROWS)]
    for row in range(GRID_ROWS):
        for col in range(GRID_COLS):
            neighbors = get_neighbors(row, col)
            if grid[row][col] == 1:
                if neighbors < 2 or neighbors > 3:
                    new_grid[row][col] = 0
                else:
                    new_grid[row][col] = 1
            else:
                if neighbors == 3:
                    new_grid[row][col] = 1
    grid = new_grid

def main_menu():
    while True:
        screen.fill((200, 200, 200))
        font = pygame.font.Font(None, 36)
        text = font.render("Configure Cells Manually", True, (0, 0, 0))
        screen.blit(text, (WIDTH // 2 - text.get_width() // 2, HEIGHT // 4))
        text = font.render("Start the Game", True, (0, 0, 0))
        screen.blit(text, (WIDTH // 2 - text.get_width() // 2, HEIGHT * 3 // 4))

        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                pygame.quit()
                sys.exit()
            if event.type == pygame.KEYDOWN:
                if event.key == pygame.K_UP:
                    current_option -= 1
                    if current_option < 0:
