                    elif current_option == 1:
                        start_game()

        pygame.display.flip()
        clock.tick(10)

def configure_cells():
    global current_option
    current_option = 0
    running = True
    while running:
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                running = False
            if event.type == pygame.MOUSEBUTTONDOWN:
