import os
import unittest

class Response:
    def __init__(self):
        self.success = False
        self.error_message = None

class ProjectOpener:
    def project_exists(self, path):
        return os.path.exists(path)

    def load_project(self, response, path):
        if not self.project_exists(path):
            response.error_message = "Project does not exist."
            return False
        # Simulate loading process
        if not os.path.isdir(path):
            response.error_message = "Path is not a directory."
            return False
        response.success = True
        return True

    def open_project(self, path, forget):
        if not self.project_exists(path):
            raise FileNotFoundError(f"Project at path {path} does not exist.")
        if not self.load_project(response=Response(), path=path):
            raise IOError(f"Failed to load project at path {path}.")
        # Simulate opening process
        if not os.path.exists(os.path.join(path, "project_file.txt")):
            raise IOError(f"Project at path {path} is not properly initialized.")
        if forget:
            # Simulate forgetting recent paths
            pass
        return True

    def initialize_results(self, response, project):
        if not response.success:
            response.error_message = "Failed to initialize results for the project."
            return
        # Simulate initializing results
        response.success = True

class TestProjectOpener(unittest.TestCase):
    def setUp(self):
        self.opener = ProjectOpener()
        self.response = Response()

    def test_project_exists(self):
        self.assertFalse(self.opener.project_exists("nonexistent_path"))
        self.assertTrue(self.opener.project_exists("/path/to/existing_project"))

    def test_load_project_success(self):
        self.assertTrue(self.opener.load_project(self.response, "/path/to/existing_project"))
        self.assertTrue(self.response.success)

    def test_load_project_failure(self):
        self.assertFalse(self.opener.load_project(self.response, "nonexistent_path"))
        self.assertEqual(self.response.error_message, "Project does not exist.")

    def test_open_project_success(self):
        self.opener.open_project("/path/to/existing_project", forget=False)
        self.assertTrue(self.response.success)

    def test_open_project_failure(self):
        with self.assertRaises(FileNotFoundError):
            self.opener.open_project("nonexistent_path", forget=False)
        with self.assertRaises(IOError):
            self.opener.open_project("/path/to/existing_project", forget=False)

    def test_initialize_results_success(self):
        self.opener.initialize_results(self.response, "/path/to/existing_project")
        self.assertTrue(self.response.success)

    def test_initialize_results_failure(self):
        self.response.success = False
        self.opener.initialize_results(self.response, "/path/to/existing_project")
        self.assertEqual(self.response.error_message, "Failed to initialize results for the project.")

if __name__ == "__main__":
    unittest.main()
