import pandas as pd
import catboost
from sklearn.metrics import accuracy_score

class CatBoostClassifierWrapper:
    name = "Catboost Classifier"
    primary_type = "classification"
    secondary_type = "None"
    tertiary_type = "tree"
    hyperparameters = {
        "n_estimators": 50,
        "max_depth": 3,
        "learning_rate": 0.1
    }

    def __init__(self, n_estimators=50, max_depth=3, learning_rate=0.1):
        self.model = catboost.CatBoostClassifier(
            iterations=n_estimators,
            max_depth=max_depth,
            learning_rate=learning_rate,
            random_state=42
        )

    def fit(self, X, y):
        if not isinstance(X, pd.DataFrame):
            raise ValueError("X must be a pandas DataFrame")
        if not isinstance(y, pd.Series):
            raise ValueError("y must be a pandas Series")
        self.model.fit(X, y)

    def predict(self, X):
        if not isinstance(X, pd.DataFrame):
            raise ValueError("X must be a pandas DataFrame")
        if X.columns.tolist() != self.model.feature_names_:
            raise ValueError("X must have the same feature columns as during fit")
        return pd.Series(self.model.predict(X))

    def score(self, X, y):
        return accuracy_score(y, self.predict(X))

    def get_params(self):
        return self.model.get_params()

