    clf.fit(X, y)
    predictions = clf.predict(X)
    assert isinstance(predictions, pd.Series)
    assert len(predictions) == len(y)
    assert 0 <= clf.score(X, y) <= 1

def test_get_params(numeric_features_binary_classification):
