```python
import pandas as pd
import tensorflow as tf

class WindowGenerator:
    def __init__(
        self,
        input_width=50,
        label_width=1,
        shift=1,
        train_df=pd.DataFrame(),
        val_df=pd.DataFrame(),
        test_df=pd.DataFrame(),
        label_columns=None,
    ):
        self.input_width = input_width
        self.label_width = label_width
        self.shift = shift
        self.train_df = train_df
        self.val_df = val_df
        self.test_df = test_df
        self.label_columns = label_columns
        self.total_train_samples = len(train_df)
        self.total_val_samples = len(val_df)
        self.total_test_samples = len(test_df)

    def split_window(self, features, labels, seq_index, label_columns=None):
        if label_columns is None:
            label_columns = self.label_columns

        input_end = -self.input_width
        label_start = self.input_width
        label_end = label_start + self.label_width

        inputs = features.iloc[input_end:seq_index].values
        labels = labels.iloc[label_start:label_end].values

        return inputs, labels

    def make_dataset(self, data, sequence_index, is_training=True):
        data = data.values
        dataset = tf.data.Dataset.from_tensor_slices((data, sequence_index))

        if is_training:
            dataset = dataset.shuffle(self.total_train_samples).batch(self.batch_size)
            dataset = dataset.map(
                lambda x, y: self.split_window(x, y, sequence_index),
                num_parallel_calls=tf.data.experimental.AUTOTUNE,
            )
            dataset = dataset.prefetch(tf.data.experimental.AUTOTUNE)
        else:
            dataset = dataset.batch(self.batch_size)
            dataset = dataset.map(
                lambda x, y: self.split_window(x, y, sequence_index),
                num_parallel_calls=tf.data.experimental.AUTOTUNE,
            )

        return dataset

    @property
    def train_ds(self):
        if not hasattr(self, "_train_ds"):
            self._train_ds = self.make_dataset(
                self.train_df, sequence_index=0, is_training=True
            )
        return self._train_ds

    @property
    def val_ds(self):
        if not hasattr(self, "_val_ds"):
            self._val_ds = self.make_dataset(
                self.val_df, sequence_index=0, is_training=False
            )
        return self._val_ds

    @property
    def test_ds(self):
        if not hasattr(self, "_test_ds"):
            self._test_ds = self.make_dataset(
                self.test_df, sequence_index=0, is_training=False
            )
        return self._test_ds

    def __repr__(self):
        return (
            f"WindowGenerator(input_width={self.input_width}, label_width={self.label_width}, "
            f"shift={self.shift}, batch_size={self.batch_size})"
        )

