```python
import boto3
from botocore.exceptions import ClientError

class SnapshotEngine:
    """
    A class to manage snapshots of a DynamoDB table.

    Attributes:
        engine_type (str): The type of the engine.
        _snapshots (list): A list of snapshot dictionaries.
    """

    def __init__(self, engine_type, snapshots=None):
        """
        Initialize the SnapshotEngine instance.

        Args:
            engine_type (str): The type of the engine.
            snapshots (list, optional): A list of snapshot dictionaries. Defaults to None.
        """
        self.engine_type = engine_type
        self._snapshots = snapshots if snapshots is not None else []

    @classmethod
    def build(cls, engine_type, table_name):
        """
        Build a SnapshotEngine instance from DynamoDB snapshots.

        Args:
            engine_type (str): The type of the engine.
            table_name (str): The name of the DynamoDB table.

        Returns:
            SnapshotEngine or None: An instance of SnapshotEngine if successful, None otherwise.
        """
        dynamodb = boto3.resource('dynamodb')
        try:
            table = dynamodb.Table(table_name)
            response = table.scan()
            snapshots = response['Items']
            return cls(engine_type, snapshots)
        except ClientError as e:
            print(f"Error retrieving snapshots for table {table_name}: {e}")
            return None

# Unit tests
import unittest

class TestSnapshotEngine(unittest.TestCase):
    def setUp(self):
        self.engine = SnapshotEngine.build('test_engine', 'test_table')

    def test_init(self):
        self.assertEqual(self.engine.engine_type, 'test_engine')
        self.assertIsNone(self.engine._snapshots)

    def test_build_with_snapshots(self):
        # Mocking the DynamoDB response
        class MockDynamoDB:
            def __init__(self):
                self.table = {
                    'Items': [
                        {'SnapshotId': 'snap1', 'CreationTime': '2023-01-01'},
                        {'SnapshotId': 'snap2', 'CreationTime': '2023-01-02'}
                    ]
                }

            def Table(self, table_name):
                return self.table

        boto3.resource = MockDynamoDB
        engine = SnapshotEngine.build('test_engine', 'test_table')
        self.assertEqual(engine.engine_type, 'test_engine')
        self.assertEqual(engine._snapshots, [
            {'SnapshotId': 'snap1', 'CreationTime': '2023-01-01'},
            {'SnapshotId': 'snap2', 'CreationTime': '2023-01-02'}
        ])

    def test_build_with_no_snapshots(self):
        # Mocking the DynamoDB response with no items
        class MockDynamoDB:
            def __init__(self):
                self.table = {
                    'Items': []
                }

            def Table(self, table_name):
                return self.table

        boto3.resource = MockDynamoDB
        engine = SnapshotEngine.build('test_engine', 'test_table')
        self.assertEqual(engine.engine_type, 'test_engine')
        self.assertIsNone(engine._snapshots)

    def test_build_with_table_not_found(self):
        # Mocking the DynamoDB error
        class MockDynamoDB:
            def __init__(self):
                self.resource = {
                    'Table': lambda name: ClientError({'Error': {'Code': 'ResourceNotFoundException'}}, 'test_table')
                }

            def resource(self, service_name):
                return self.resource

        boto3.resource = MockDynamoDB
        engine = SnapshotEngine.build('test_engine', 'test_table')
        self.assertIsNone(engine)

if __name__ == '__main__':
    unittest.main()
```

