To create the `pulp-cli` CLI application, we'll use the `click` library for command-line interface creation and `toml` library for handling TOML files. For secure handling of sensitive information, we'll use the `getpass` library to hide password input.

First, install the required libraries:

```bash
pip install click toml getpass
```

Now, let's create the `pulp-cli.py` file:

```python
import os
import sys
import click
import toml
from getpass import getpass

DEFAULT_CONFIG = {
    "base_url": "https://example.com",
    "username": "",
    "password": "",
    "cert": "",
    "key": "",
    "verify_ssl": True,
    "format": "json",
    "dry_run": False,
    "timeout": 60,
    "verbose": False,
}

def create_config(interactive=False, editor=None, overwrite=False):
    if interactive:
        config = {}
        for key, value in DEFAULT_CONFIG.items():
            if value == "":
                config[key] = input(f"Enter {key} (or leave blank for default): ") or value
            else:
                config[key] = value
    else:
        config = DEFAULT_CONFIG

    if editor:
        file_path = editor(config)
    else:
        file_path = "pulp.toml"

    if os.path.exists(file_path) and not overwrite:
        click.echo(f"File '{file_path}' already exists. Use --overwrite to overwrite it.")
        sys.exit(1)

    with open(file_path, "w") as f:
        toml.dump(config, f)

    click.echo(f"Configuration file created at '{file_path}'")

def edit_config(editor):
    file_path = "pulp.toml"
    if not os.path.exists(file_path):
        click.echo(f"File '{file_path}' does not exist.")
        sys.exit(1)

    config = toml.load(file_path)
    editor(config)

    with open(file_path, "w") as f:
        toml.dump(config, f)

    click.echo(f"Configuration file edited and saved to '{file_path}'")

def validate_config(file_path):
    if not os.path.exists(file_path):
        click.echo(f"File '{file_path}' does not exist.")
        sys.exit(1)

    try:
        toml.load(file_path)
        click.echo(f"File '{file_path}' is valid.")
    except toml.TomlDecodeError as e:
        click.echo(f"File '{file_path}' is invalid: {e}")

@click.group()
def cli():
    pass

@cli.command("create")
@click.option("--interactive/--no-interactive", default=False, help="Use interactive mode to set config values.")
@click.option("--editor", help="Specify an external editor to use for editing the config file.")
@click.option("--overwrite/--no-overwrite", default=False, help="Overwrite an existing config file.")
def create(interactive, editor, overwrite):
    create_config(interactive, editor, overwrite)

@cli.command("edit")
@click.option("--editor", help="Specify an external editor to use for editing the config file.")
def edit(editor):
    edit_config(editor)

@cli.command("validate")
@click.argument("file_path")
def validate(file_path):
    validate_config(file_path)

if __name__ == "__main__":
    cli()
```

To run the application, execute:

```bash
python pulp-cli.py create --interactive
python pulp-cli.py edit --editor "vi"
python pulp-cli.py validate pulp.toml
```

For testing, you can use the `unittest` library to create test cases for each command. Here's an example of how to test the `create` command:

```python
import unittest
import os
import tempfile
from pulp_cli import create_config, DEFAULT_CONFIG

class TestPulpCLI(unittest.TestCase):
    def setUp(self):
        self.temp_dir = tempfile.TemporaryDirectory()
        self.config_path = os.path.join(self.temp_dir.name, "pulp.toml")

    def tearDown(self):
        self.temp_dir.cleanup()

    def test_create_config(self):
        create_config(interactive=True, editor=None, overwrite=True)
        with open(self.config_path, "r") as f:
            config = toml.load(f)
        self.assertEqual(config, DEFAULT_CONFIG)

if __name__ == "__main__":
    unittest.main()
```

This test case creates a temporary directory, runs the `create` command, and checks if the generated configuration file matches the default configuration. You can create similar test cases for the `edit` and `validate` commands.

