        super().__init__(image_shapes, filter_sizes, modes, data_types)

    def run_benchmark(self, bench_func):
        super().run_benchmark(bench_func)

class ConvolveBench(ImageBench):
    def __init__(self, image_shapes, filter_sizes, modes, data_types):
        super().__init__(image_shapes, filter_sizes, modes, data_types)

    def run_benchmark(self, bench_func):
        super().run_benchmark(bench_func)

def benchmark_filter(image, size, mode, dtype, device):
    if device == 'cpu':
        if mode == 'uniform':
            return uniform_filter(image, size=size, mode=mode)
        elif mode == 'gaussian':
            return gaussian_filter(image, sigma=size, mode=mode)
        elif mode == 'max':
            return maximum_filter(image, size=size, mode=mode)
        elif mode == 'min':
            return minimum_filter(image, size=size, mode=mode)
        elif mode == 'median':
            return median_filter(image, size=size, mode=mode)
        elif mode == 'percentile':
            return percentile_filter(image, 50, size=size, mode=mode)
        elif mode == 'rank':
            return rank_filter(image, size=size, mode=mode)
        else:
            raise ValueError("Invalid filter mode")
    elif device == 'gpu':
        if mode == 'uniform':
            return cupy_uniform_filter(image, size=size, mode=mode)
        elif mode == 'gaussian':
            return cupy_gaussian_filter(image, sigma=size, mode=mode)
        elif mode == 'max':
            return cupy_maximum_filter(image, size=size, mode=mode)
        elif mode == 'min':
            return cupy_minimum_filter(image, size=size, mode=mode)
        elif mode == 'median':
            return cupy_median_filter(image, size=size, mode=mode)
        elif mode == 'percentile':
            return cupy_percentile_filter(image, 50, size=size, mode=mode)
        elif mode == 'rank':
            return cupy_rank_filter(image, size=size, mode=mode)
        else:
            raise ValueError("Invalid filter mode")
    else:
        raise ValueError("Invalid device")

def benchmark_convolve(image, kernel, mode, dtype, device):
    if device == 'cpu':
        return convolve(image, kernel, mode=mode)
    elif device == 'gpu':
        return cupy_convolve(image, kernel, mode=mode)
    else:
        raise ValueError("Invalid device")

def run_benchmarks():
    image_shapes = [(100, 100), (200, 200), (500, 500)]
    filter_sizes = [3, 5, 7]
    modes = ['uniform', 'gaussian', 'max', 'min', 'median', 'percentile', 'rank']
    data_types = [np.float32, np.float64]

    filter_bench = FilterBench(image_shapes, filter_sizes, modes, data_types)
    convolve_bench = ConvolveBench(image_shapes, filter_sizes, modes, data_types)

    # Generate a random kernel for convolution
    kernel = np.random.rand(3, 3).astype(np.float32)

    # Run filter benchmarks
    filter_bench.run_benchmark(benchmark_filter)

    # Run convolution benchmarks
    convolve_bench.run_benchmark(lambda img, size, mode, dtype, device: benchmark_convolve(img, kernel, mode, dtype, device))

    # Save results
    output_dir = 'benchmarks_output'
    os.makedirs(output_dir, exist_ok=True)
    filter_bench.results.to_csv(os.path.join(output_dir, 'filter_results.csv'), index=False)
    filter_bench.results.to_pickle(os.path.join(output_dir, 'filter_results.pkl'))
    with open(os.path.join(output_dir, 'filter_results.md'), 'w') as f:
        f.write(filter_bench.results.to_markdown())

    convolve_bench.results.to_csv(os.path.join(output_dir, 'convolve_results.csv'), index=False)
    convolve_bench.results.to_pickle(os.path.join(output_dir, 'convolve_results.pkl'))
    with open(os.path.join(output_dir, 'convolve_results.md'), 'w') as f:
        f.write(convolve_bench.results.to_markdown())

if __name__ == "__main__":
    run_benchmarks()
