import json
import boto3
from aws_lambda_powertools import Logger, Tracer, Metrics

logger = Logger()
tracer = Tracer()
metrics = Metrics()

s3 = boto3.client('s3')

@tracer.capture_lambda_handler
def lambda_handler(event, context):
    try:
        bucket_name = event['Records'][0]['s3']['bucket']['name']
        key = event['Records'][0]['s3']['object']['key']

        response = s3.get_object(Bucket=bucket_name, Key=key)
        content = response['Body'].read().decode('utf-8', errors='replace')

        logger.info(f"S3 Object Content: {content}")
        metrics.record_metric(name="S3ObjectProcessed", value=1, unit="count")

        return {
            'statusCode': 200,
            'body': json.dumps({
                'content': content,
                'event': event
            })
        }

    except Exception as e:
        logger.error(f"Error processing S3 object: {e}")
        return {
            'statusCode': 500,
            'body': json.dumps({'error': str(e)})
        }

# Unit tests
import unittest

class TestLambdaHandler(unittest.TestCase):
    def test_valid_s3_event(self):
        # Mock S3 event and response
        event = {
            'Records': [
                {
                    's3': {
                        'bucket': {'name': 'test-bucket'},
                        'object': {
                            'key': 'test-key'
                        }
                    }
                }
            ]
        }
        response = {
            'Body': b'Test content'
        }
        s3.get_object.return_value = response

        result = lambda_handler(event, None)
        self.assertEqual(result['statusCode'], 200)
        self.assertIn('content', result['body'])
        s3.get_object.assert_called_with(Bucket='test-bucket', Key='test-key')

    def test_invalid_s3_event(self):
        event = {
            'Records': [
                {
                    's3': {
                        'bucket': {'name': 'non-existent-bucket'},
                        'object': {
                            'key': 'non-existent-key'
                        }
                    }
                }
            ]
        }

        result = lambda_handler(event, None)
        self.assertEqual(result['statusCode'], 500)
        self.assertIn('error', result['body'])

if __name__ == '__main__':
