class MetadataFormatType:
    def __init__(self, prefix, schema, namespace):
        self.prefix = prefix
        self.schema = schema
        self.namespace = namespace

    def __repr__(self):
        return f"MetadataFormatType(prefix={self.prefix}, schema={self.schema}, namespace={self.namespace})"


class ListMetadataFormatsType:
    def __init__(self):
        self.formats = []

    def add_format(self, format):
        if isinstance(format, MetadataFormatType):
            if any(f.prefix == format.prefix for f in self.formats):
                raise ValueError(f"Format with prefix {format.prefix} already exists.")
            self.formats.append(format)
        else:
            raise TypeError("Only instances of MetadataFormatType can be added.")

    def get_formats(self):
        return self.formats

    def find_format(self, prefix):
        if prefix == "":
            return None
        return next((f for f in self.formats if f.prefix == prefix), None)


