import uuid

class FinancialTransactionProtocol:
    def __init__(self):
        self.transactions = {}
        self.confirmations = {}

    class Transaction:
        def __init__(self, sender, receiver, amount, currency):
            self.transaction_id = str(uuid.uuid4())
            self.sender = sender
            self.receiver = receiver
            self.amount = amount
            self.currency = currency

        @property
        def sender(self):
            return self._sender

        @sender.setter
        def sender(self, value):
            if not isinstance(value, str):
                raise ValueError("Sender must be a string")
            self._sender = value

        @property
        def receiver(self):
            return self._receiver

        @receiver.setter
        def receiver(self, value):
            if not isinstance(value, str):
                raise ValueError("Receiver must be a string")
            self._receiver = value

        @property
        def amount(self):
            return self._amount

        @amount.setter
        def amount(self, value):
            if not isinstance(value, (int, float)) or value < 0:
                raise ValueError("Amount must be a non-negative number")
            self._amount = value

        @property
        def currency(self):
            return self._currency

        @currency.setter
        def currency(self, value):
            if not isinstance(value, str):
                raise ValueError("Currency must be a string")
            self._currency = value

        def to_dict(self):
            return {
                "transaction_id": self.transaction_id,
                "sender": self.sender,
                "receiver": self.receiver,
                "amount": self.amount,
                "currency": self.currency
            }

    class Confirmation:
        def __init__(self, transaction_id, success):
            if transaction_id not in self.transactions:
                raise ValueError("Invalid transaction ID")
            self.transaction_id = transaction_id
            self.success = success

        @property
        def transaction_id(self):
            return self._transaction_id

        @transaction_id.setter
        def transaction_id(self, value):
            if value not in self.transactions:
                raise ValueError("Invalid transaction ID")
            self._transaction_id = value

        @property
        def success(self):
            return self._success

        @success.setter
        def success(self, value):
            if not isinstance(value, bool):
                raise ValueError("Success must be a boolean")
            self._success = value

        def to_dict(self):
            return {
                "transaction_id": self.transaction_id,
                "success": self.success
            }

    def create_transaction(self, sender, receiver, amount, currency):
        transaction = self.Transaction(sender, receiver, amount, currency)
        self.transactions[transaction.transaction_id] = transaction
        return transaction

    def create_confirmation(self, transaction_id, success):
        confirmation = self.Confirmation(transaction_id, success)
        self.confirmations[confirmation.transaction_id] = confirmation
        return confirmation

    def is_valid_transaction(self, transaction):
        if transaction.transaction_id not in self.transactions:
            return False
        if transaction.amount < 0:
            return False
        return True

    def is_valid_confirmation(self, confirmation):
        if confirmation.transaction_id not in self.transactions:
            return False
        return True
