from functools import wraps

# Dictionary to store job details
jobs = {}

def job(depends_on=None, desc=None):
    """Decorator to mark a function as a job with optional dependencies and description."""
    def decorator(func):
        jobs[func.__name__] = {'depends_on': depends_on, 'description': desc}
        @wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper
    return decorator

def run_job(job_name):
    """Runs a job and its dependencies in the correct order."""
    if job_name not in jobs:
        raise ValueError(f"Job '{job_name}' does not exist.")

    job_details = jobs[job_name]
    for dep in job_details['depends_on'] or []:
        if dep not in jobs:
            raise ValueError(f"Dependency '{dep}' for job '{job_name}' does not exist.")
        run_job(dep)

    print(f"Running job: {job_name} - {job_details['description']}")
    jobs[job_name]['wrapper']()

def list_jobs():
    """Lists all registered jobs with their descriptions and dependencies."""
    for job_name, details in jobs.items():
        print(f"Job: {job_name}")
        print(f"  Description: {details['description']}")
        print(f"  Depends on: {', '.join(details['depends_on']) if details['depends_on'] else 'None'}")
        print()

# Example usage

@job(depends_on=['job1'], desc="This job depends on job1 and does some work.")
def job2():
    print("Job 2 is running")

@job(desc="This is the base job.")
def job1():
    print("Job 1 is running")

# Registering jobs
run_job('job1')
run_job('job2')

# Listing jobs
list_jobs()
```

