import re
from django.http import JsonResponse
from django.urls import path
from django.views.generic import ListView, DetailView
from .models import Outlet  # Assuming Outlet model exists

# Define the UUID regex pattern
UUID_REGEX = re.compile(r'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$')

class OutletList(ListView):
    model = Outlet
    context_object_name = 'outlets'
    template_name = 'outlets/outlet_list.html'  # Assuming this template exists

    def get_queryset(self):
        return Outlet.objects.all()

    def render_to_response(self, context, **response_kwargs):
        return JsonResponse(list(context['outlets'].values('id', 'name', 'location')), safe=False)

class OutletDetail(DetailView):
    model = Outlet
    context_object_name = 'outlet'
    template_name = 'outlets/outlet_detail.html'  # Assuming this template exists

    def get_object(self, queryset=None):
        uuid = self.kwargs.get('uuid')
        if not UUID_REGEX.match(uuid):
            raise ValueError("Invalid UUID format")
        try:
            return Outlet.objects.get(id=uuid)
        except Outlet.DoesNotExist:
            raise Http404("Outlet not found")

    def render_to_response(self, context, **response_kwargs):
        return JsonResponse(context['outlet'].to_dict(fields=('id', 'name', 'location')), safe=False)

# Define URL patterns
urlpatterns = [
    path('', OutletList.as_view(), name='outlet-list'),
    path('<uuid:uuid>/', OutletDetail.as_view(), name='outlet-detail'),
]
```

