import unittest

class TestDynamoDBSessionStore(unittest.TestCase):
    def setUp(self):
        self.store = DynamoDBSessionStore('test-table')

    def test_load_session(self):
        # Test loading a non-existent session
        self.assertIsNone(self.store.load_session('nonexistent_key'))

        # Test loading an existing session
        self.store.create_session('existing_key', {'test': 'data'})
        loaded_session = self.store.load_session('existing_key')
        self.assertEqual(loaded_session, {'session_key': 'existing_key', 'session_data': self.store._encrypt_data({'test': 'data'})})

    def test_session_exists(self):
        # Test checking for a non-existent session
        self.assertFalse(self.store.session_exists('nonexistent_key'))

        # Test checking for an existing session
        self.store.create_session('existing_key', {'test': 'data'})
        self.assertTrue(self.store.session_exists('existing_key'))

    def test_create_session(self):
        # Test creating a new session
        self.store.create_session('new_key', {'test': 'data'})
        self.assertTrue(self.store.session_exists('new_key'))

        # Test creating a session that already exists
        self.assertFalse(self.store.create_session('existing_key', {'test': 'data'}))

    def test_save_session(self):
        # Test saving a new session
        self.store.create_session('new_key', {'test': 'data'})
        self.store.save_session('new_key', {'updated_test': 'updated_data'})
        updated_session = self.store.load_session('new_key')
        self.assertEqual(updated_session, {'session_key': 'new_key', 'session_data': self.store._encrypt_data({'updated_test': 'updated_data'})})

        # Test saving to an existing session
        self.store.create_session('existing_key', {'test': 'data'})
        self.store.save_session('existing_key', {'updated_test': 'updated_data'})
        updated_session = self.store.load_session('existing_key')
        self.assertEqual(updated_session, {'session_key': 'existing_key', 'session_data': self.store._encrypt_data({'updated_test': 'updated_data'})})

    def test_delete_session(self):
        # Test deleting a non-existent session
        self.assertFalse(self.store.delete_session('nonexistent_key'))

        # Test deleting an existing session
        self.store.create_session('existing_key', {'test': 'data'})
        self.assertTrue(self.store.delete_session('existing_key'))
        self.assertFalse(self.store.session_exists('existing_key'))

if __name__ == '__main__':
