```python
from pymongo import MongoClient
from datetime import datetime

# Connect to MongoDB
client = MongoClient('mongodb://localhost:27017/')
db = client['employee_db']

attendance_collection = db['attendance']
emp_collection = db['emp']

def validate_date(date_str):
    try:
        return datetime.strptime(date_str, '%Y-%m-%d')
    except ValueError:
        return None

def validate_id(id_str):
    if not id_str.isdigit():
        return None
    return int(id_str)

def insert_attendance(emp_id, name, date, time):
    try:
        emp_id = validate_id(emp_id)
        date = validate_date(date)
        if not emp_id or not date:
            raise ValueError("Invalid input")
        attendance_record = {
            'emp_id': emp_id,
            'name': name,
            'date': date,
            'time': time
        }
        attendance_collection.insert_one(attendance_record)
        return "Attendance record inserted successfully."
    except Exception as e:
        return str(e)

def fetch_all_attendance():
    try:
        records = list(attendance_collection.find())
        return records
    except Exception as e:
        return str(e)

def fetch_by_date(date_str):
    date = validate_date(date_str)
    if not date:
        return "Invalid date format. Use YYYY-MM-DD."
    try:
        records = list(attendance_collection.find({'date': date}))
        return records
    except Exception as e:
        return str(e)

def fetch_by_id(emp_id_str):
    emp_id = validate_id(emp_id_str)
    if not emp_id:
        return "Invalid employee ID."
    try:
        records = list(attendance_collection.find({'emp_id': emp_id}))
        return records
    except Exception as e:
        return str(e)

def fetch_by_id_and_date(emp_id_str, date_str):
    emp_id = validate_id(emp_id_str)
    date = validate_date(date_str)
    if not emp_id or not date:
        return "Invalid input."
    try:
        records = list(attendance_collection.find({'emp_id': emp_id, 'date': date}))
        return records
    except Exception as e:
        return str(e)

def get_employee_phone(emp_id_str):
    emp_id = validate_id(emp_id_str)
    if not emp_id:
        return "Invalid employee ID."
    try:
        record = emp_collection.find_one({'_id': emp_id})
        if record and 'phone' in record:
            return record['phone']
        else:
            return "Phone number not found for this employee."
    except Exception as e:
        return str(e)

# Test cases
print(insert_attendance(1, 'John Doe', '2022-01-01', '09:00:00'))
print(fetch_all_attendance())
print(fetch_by_date('2022-01-01'))
print(fetch_by_id('1'))
print(fetch_by_id_and_date('1', '2022-01-01'))
print(get_employee_phone('1'))
```

This program connects to a MongoDB instance running on localhost, and it defines functions to insert and fetch attendance records, as well as to retrieve an employee's phone number. Each function includes input validation and error handling. The test cases at the end demonstrate how to use these functions.

Please note that this code assumes that the MongoDB server is running on the local machine and that the 'employee_db' database and 'attendance' and 'emp' collections already exist. You may need to adjust the connection string and database/collection names according to your specific setup.

Also, for security reasons, sensitive data like phone numbers should be encrypted or hashed before storing in the database. This example does not include such measures for simplicity.

