import numpy as np
import random
from scipy.spatial import distance
import time

def generate_graph(num_nodes):
    # Generate random (x, y) coordinates for each node
    coords = np.random.rand(num_nodes, 2)

    # Initialize adjacency matrix with zeros
    adj_matrix = np.zeros((num_nodes, num_nodes), dtype=int)

    # Connect each node to its three nearest neighbors
    for i in range(num_nodes):
        distances = distance.cdist([coords[i]], coords)[0]
        sorted_indices = np.argsort(distances)[:3]
        for j in sorted_indices:
            if j != i and adj_matrix[i][j] == 0:
                adj_matrix[i][j] = 1
                adj_matrix[j][i] = 1

    return coords, adj_matrix

def is_fully_connected(adj_matrix):
    return np.all(np.any(adj_matrix, axis=1)) and np.all(np.any(adj_matrix, axis=0))

def is_diameter_4(adj_matrix):
    n = len(adj_matrix)
    floyd_warshall = np.full((n, n, n), np.inf)

    for i in range(n):
        floyd_warshall[i][i] = 0

    for i in range(n):
        for j in range(n):
            if adj_matrix[i][j] == 1:
                floyd_warshall[i][j] = 1
                floyd_warshall[j][i] = 1

    for k in range(n):
        for i in range(n):
            for j in range(n):
                floyd_warshall[i][j] = min(floyd_warshall[i][j], floyd_warshall[i][k] + floyd_warshall[k][j])

    return max(max(row) for row in floyd_warshall) <= 4

def degree_3(adj_matrix):
    return np.all(np.sum(adj_matrix, axis=1) == 3) and np.all(np.sum(adj_matrix, axis=0) == 3)

def total_cost(coords, adj_matrix):
    return np.sum(distance.cdist(coords[adj_matrix == 1], coords[adj_matrix == 1]))

def greedy_local_search(coords, adj_matrix, max_iterations=100):
    start_time = time.time()
    total_cost_before = total_cost(coords, adj_matrix)
    iterations = 0

    while iterations < max_iterations:
        # Find the most expensive edge
        expensive_edge = np.unravel_index(np.argmax(distance.cdist(coords[adj_matrix == 1], coords[adj_matrix == 1])), adj_matrix.shape)

        # Remove the edge
        adj_matrix[expensive_edge] = 0
        adj_matrix[expensive_edge[::-1]] = 0

        # Check if constraints are still satisfied
        if not is_fully_connected(adj_matrix) or not is_diameter_4(adj_matrix) or not degree_3(adj_matrix):
            # If not, add the edge back and continue
            adj_matrix[expensive_edge] = 1
            adj_matrix[expensive_edge[::-1]] = 1
            continue

        total_cost_after = total_cost(coords, adj_matrix)

        if total_cost_after < total_cost_before:
            total_cost_before = total_cost_after

        iterations += 1

    end_time = time.time()
    return coords, adj_matrix, total_cost_before, end_time - start_time

def heuristic_algorithm(num_nodes):
    coords, adj_matrix = generate_graph(num_nodes)

    while not is_diameter_4(adj_matrix) or not degree_3(adj_matrix):
        coords, adj_matrix = generate_graph(num_nodes)

    return coords, adj_matrix, total_cost(coords, adj_matrix)

def run_tests():
    num_nodes = 10
    coords, adj_matrix, cost_before = generate_graph(num_nodes)

    assert is_fully_connected(adj_matrix), "Graph is not fully connected"
    assert is_diameter_4(adj_matrix), "Graph diameter is not 4"
    assert degree_3(adj_matrix), "Nodes do not have degree 3"

    coords, adj_matrix, cost_after_greedy, _ = greedy_local_search(coords, adj_matrix)
    coords, adj_matrix, cost_after_heuristic, _ = heuristic_algorithm(num_nodes)

    print(f"Original total cost: {cost_before}")
    print(f"Greedy local search total cost: {cost_after_greedy}")
    print(f"Heuristic algorithm total cost: {cost_after_heuristic}")

run_tests()
