```python
import string

def caesar_encrypt(text, shift):
    if len(text) > 4096:
        raise ValueError("Input text exceeds the maximum allowed length of 4096 characters.")

    encrypted_text = ""
    for char in text:
        if char.isalpha():
            ascii_offset = ord('a') if char.islower() else ord('A')
            encrypted_text += chr((ord(char) - ascii_offset + shift) % 26 + ascii_offset)
        else:
            encrypted_text += char
    return encrypted_text

def binary_decode(binary_string):
    try:
        decoded_text = ''.join(chr(int(binary_string[i:i+8], 2)) for i in range(0, len(binary_string), 8))
        return decoded_text
    except (ValueError, IndexError):
        raise ValueError("Invalid binary string. Ensure it's a multiple of 8 bits long.")

def main():
    while True:
        print("\n1. Encrypt text using Caesar cipher")
        print("2. Decrypt binary string to text")
        print("3. Exit")
        choice = input("Enter your choice: ")

        if choice == '1':
            text = input("Enter the text to encrypt: ")
            shift = int(input("Enter the shift value: "))
            try:
                encrypted_text = caesar_encrypt(text, shift)
                print(f"Encrypted text: {encrypted_text}")
            except ValueError as e:
                print(e)

        elif choice == '2':
            binary_string = input("Enter the binary string to decode: ")
            try:
                decoded_text = binary_decode(binary_string)
                print(f"Decoded text: {decoded_text}")
            except ValueError as e:
                print(e)

        elif choice == '3':
            break

        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
