To create the Django application as described, follow these steps:

1. Create a new Django project and app:

```bash
django-admin startproject wallhaven_search
cd wallhaven_search
django-admin startapp wallpaper_app
```

2. Add `wallpaper_app` to the `INSTALLED_APPS` list in `wallhaven_search/settings.py`:

```python
INSTALLED_APPS = [
    # ...
    'wallpaper_app',
]
```

3. Create the `WallpaperForm` in `wallpaper_app/forms.py`:

```python
from django import forms

class WallpaperForm(forms.Form):
    search_phrase = forms.CharField(label='Search Phrase', max_length=100)
    random = forms.BooleanField(label='Get Random Wallpapers', required=False)
```

4. Implement the `convert_images` function in `wallpaper_app/helpers.py`:

```python
import requests
from PIL import Image
from io import BytesIO
import base64

def convert_images(search_phrase, random):
    base_url = 'https://wallhaven.cc/wallpaper'
    params = {'q': search_phrase, 'sort': 'random' if random else 'top'}

    try:
        response = requests.get(base_url, params=params)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        return [], f"Error fetching images: {e}"

    images = []
    for image_data in response.iter_content(1024):
        img = Image.open(BytesIO(image_data))
        img_io = BytesIO()
        img.save(img_io, format=img.format)
        img_io.seek(0)
        images.append((img.format, base64.b64encode(img_io.read()).decode('utf-8')))

    return images
```

5. Implement the `wallpaper` view function in `wallpaper_app/views.py`:

```python
from django.shortcuts import render
from .forms import WallpaperForm
from .helpers import convert_images

def wallpaper(request):
    if request.method == 'POST':
        form = WallpaperForm(request.POST)
        if form.is_valid():
            search_phrase = form.cleaned_data['search_phrase']
            random = form.cleaned_data['random']
            images = convert_images(search_phrase, random)
            return JsonResponse({'images': images})
    else:
        form = WallpaperForm()

    return render(request, 'home.html', {'form': form})
```

6. Create the `home.html` template in `wallpaper_app/templates/wallpaper_app/`:

```html
{% extends 'base.html' %}

{% block content %}
  <h1>Wallhaven Search</h1>
  <form method="post">
    {% csrf_token %}
    {{ form.as_p }}
    <button type="submit">Search</button>
  </form>
  {% if images %}
    <div id="search-results">
      {% for ext, img_data in images %}
        <img src="data:image/{{ ext }};base64,{{ img_data }}" alt="Wallpaper Thumbnail">
      {% empty %}
        <p>No images found.</p>
      {% endfor %}
    </div>
  {% endif %}
  <script>
    document.querySelector('form').addEventListener('submit', function(e) {
      e.preventDefault();
      const formData = new FormData(this);
      fetch(this.action, {
        method: this.method,
        body: formData
      })
      .then(response => response.json())
      .then(data => {
        const searchResults = document.getElementById('search-results');
        searchResults.innerHTML = '';
        data.images.forEach(image => {
          const img = document.createElement('img');
          img.src = `data:image/${image[0]};base64,${image[1]}`;
          searchResults.appendChild(img);
        });
      })
      .catch(error => {
        console.error('Error fetching images:', error);
      });
    });
  </script>
{% endblock %}
```

