```python
import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import DataLoader

class PyTorchModelInterface:
    def __init__(self, model=None, model_path=None, transformer=None, device='cpu'):
        self.model = model
        self.model_path = model_path
        self.transformer = transformer
        self.device = device
        self.set_eval_mode()

        if model_path is not None:
            self.load_model(model_path)

    def load_model(self, model_path):
        try:
            self.model = torch.load(model_path, map_location=self.device)
            self.model.eval()
        except FileNotFoundError:
            raise FileNotFoundError(f"Model file not found at {model_path}")
        except Exception as e:
            raise e

    def predict(self, inp, transform_data=False):
        if transform_data and self.transformer is not None:
            inp = self.transformer.transform(inp)

        if not isinstance(inp, torch.Tensor):
            raise TypeError("Input must be a PyTorch tensor")

        if inp.device != self.device:
            inp = inp.to(self.device)

        if inp.ndim != 2:
            raise ValueError("Input tensor must be 2-dimensional")

        with torch.no_grad():
            output = self.model(inp)

        return output.cpu().detach().numpy()

    def set_eval_mode(self):
        if self.model is not None:
            self.model.eval()

    def get_num_output_nodes(self, inp_size):
        if self.model is None:
            raise RuntimeError("Model not loaded. Call load_model() first.")

        dummy_input = torch.randn(1, inp_size).to(self.device)
        with torch.no_grad():
            output = self.model(dummy_input)

        return output.size(1)

