    "user1": generate_password_hash("password1"),
    "user2": generate_password_hash("password2")
}

# Mock leaks database
leaks = {}

@auth.verify_password
def verify_password(username, password):
    if username in users and check_password_hash(users.get(username), password):
        return username

class LeakResource(Resource):
    @auth.login_required
    def post(self, leak_id):
        if not request.json or 'url' not in request.json:
            return {"message": "Missing parameters"}, 400

        url = request.json['url']
        if leak_id in leaks:
            return {"message": f"Leak with ID {leak_id} already exists."}, 409

        leaks[leak_id] = url
        return {"message": f"Leak with ID {leak_id} created successfully."}, 201

    @auth.login_required
    def get(self, leak_id=None):
        if leak_id:
            if leak_id not in leaks:
                return {"message": f"Leak with ID {leak_id} not found."}, 404
            return {"message": f"Leak with ID {leak_id} found."}, leaks[leak_id]
        else:
            return {"message": f"Leaks found: {list(leaks.keys())}"}, list(leaks.keys())

    @auth.login_required
    def delete(self, leak_id):
        if leak_id not in leaks:
            return {"message": f"Leak with ID {leak_id} not found."}, 404

        del leaks[leak_id]
        return {"message": f"Leak with ID {leak_id} deleted successfully."}, 200

api.add_resource(LeakResource, '/api/v2/leak/general/', '/api/v2/leak/general/<string:leak_id>')

