```python
def count_substring_occurrences(text, substring):
    if not text or not substring:
        return 0

    def bad_char_heuristic(s, t):
        bad_char_table = {}
        for i in range(len(t) - 1):
            bad_char_table[t[i]] = len(t) - 1 - i
        return bad_char_table

    def good_suffix_heuristic(s, t):
        good_suffix_table = {}
        for i in range(len(t)):
            good_suffix_table[t[i]] = len(t) - 1 - i
        return good_suffix_table

    def boyer_moore(text, pattern):
        m, n = len(pattern), len(text)
        if m == 0:
            return float('inf')
        if n == 0:
            return 0

        bad_char_table = bad_char_heuristic(pattern, text)
        good_suffix_table = good_suffix_heuristic(pattern, text)

        skip = m - 1
        i = skip
        while i < n:
            j = m - 1
            while j >= 0 and pattern[j] == text[i - j]:
                j -= 1
            if j < 0:
                return i - m + 1
            else:
                skip_amount = skip - max(bad_char_table.get(text[i], m), good_suffix_table.get(pattern[j], m))
                i += skip_amount

        return 0

    count = 0
    while True:
        pos = boyer_moore(text, substring)
        if pos == float('inf'):
            break
        count += 1
        text = text[pos + len(substring):]

    return count
```

