def find_diagonal_order(matrix):
    if not all(isinstance(row, list) for row in matrix):
        raise ValueError("Input must be a 2D list")
    if not all(all(isinstance(val, int) for val in row) for row in matrix):
        raise ValueError("All elements in the matrix must be integers")

    result = []
    rows, cols = len(matrix), len(matrix[0])
    up_right = True  # True for up-right, False for down-left

    for d in range(rows + cols - 1):
        if up_right:
            for r in range(min(d + 1, rows)):
                c = d - r
                if 0 <= c < cols:
                    result.append(matrix[r][c])
        else:
            for c in range(max(0, d - rows + 1), min(d + 1, cols)):
                r = d - c
                if 0 <= r < rows:
                    result.append(matrix[r][c])
        up_right = not up_right

    return result
```

