// Verification interface for different verification implementations
interface Verification {
    boolean verify(Customer customer);
}

// CustomerVerificationResult class representing the result of the verification process
class CustomerVerificationResult {
    private boolean passed;

    public CustomerVerificationResult(boolean passed) {
        this.passed = passed;
    }

    public boolean isPassed() {
        return passed;
    }
}

// CustomerVerifier class that can verify a customer using multiple verifications
class CustomerVerifier {
    private Set<Verification> verifications;

    public CustomerVerifier(Set<Verification> verifications) {
        this.verifications = verifications;
    }

    public CustomerVerificationResult verify(Customer customer) {
        boolean allPassed = true;
        for (Verification verification : verifications) {
            if (customer == null) {
                // Handle null customer gracefully
                allPassed = false;
                break;
            }
            if (!verification.verify(customer)) {
                allPassed = false;
                break;
            }
        }
        return new CustomerVerificationResult(allPassed);
    }
}

// Example verification implementations
class EmailVerification implements Verification {
    @Override
    public boolean verify(Customer customer) {
        // Simple email verification logic
        return customer.getEmail() != null && !customer.getEmail().isEmpty();
    }
}

class AddressVerification implements Verification {
