import datetime
import dateutil.parser

class CongressError(Exception):
    """Base class for Congress API errors."""
    def __init__(self, message, response=None, url=None):
        super().__init__(message)
        self.response = response
        self.url = url

class NotFound(CongressError):
    """Exception for items not found in the Congress API."""
    pass

def check_chamber(chamber):
    """Validate the chamber input."""
    valid_chambers = ['house', 'senate', 'both']
    if chamber not in valid_chambers:
        raise TypeError(f"Invalid chamber: {chamber}. Must be one of {valid_chambers}")

def get_congress(year):
    """Calculate the Congress number for a given year."""
    if year < 1789:
        raise CongressError(f"Congress did not exist in {year}. The first Congress started in 1789.")
    return (year - 1789) // 2 + 1

def parse_date(date_str):
    """Parse a date string into a datetime object."""
    try:
        return dateutil.parser.parse(date_str)
    except (ValueError, TypeError):
        pass
    return datetime.datetime.strptime(date_str, '%Y-%m-%d').date()

def u(text):
    """Ensure text is a Unicode string with LF line endings."""
    if isinstance(text, bytes):
        text = text.decode('utf-8')
    if isinstance(text, str):
        text = text.replace('\r\n', '\n')
    return text

def get_offset(page):
    """Calculate the offset for pagination."""
    if page < 1:
        raise CongressError(f"Invalid page number: {page}. Page numbers must be 1 or greater.")
    return (page - 1) * 20

CURRENT_CONGRESS = get_congress(datetime.datetime.now().year)

# Test cases
if __name__ == "__main__":
    # Test CongressError
    try:
        get_congress(1788)
    except CongressError as e:
        print(e)  # Should print: Congress did not exist in 1788. The first Congress started in 1789.

    # Test NotFound
    try:
        raise NotFound("Item not found")
    except NotFound as e:
        print(e)  # Should print: Item not found

    # Test check_chamber
    try:
        check_chamber('invalid')
    except TypeError as e:
        print(e)  # Should print: Invalid chamber: invalid. Must be one of ['house', 'senate', 'both']

    # Test parse_date
    print(parse_date('2022-01-01'))  # Should print a datetime.date object

    # Test u
    print(u(b'Hello\r\nWorld'))  # Should print: Hello\nWorld

    # Test get_offset
    print(get_offset(1))  # Should print: 0
    try:
        get_offset(0)
    except CongressError as e:
        print(e)  # Should print: Invalid page number: 0. Page numbers must be 1 or greater.

    # Test CURRENT_CONGRESS
    print(CURRENT_CONGRESS)  # Should print the current Congress number
```

