```python
import random
import sys
from colorama import Fore, Style, init

init(autoreset=True)

def create_maze(width, height):
    if width % 2 == 0 or height % 2 == 0 or width < 3 or height < 3:
        raise ValueError("Width and height must be odd integers greater than 1.")

    maze = [['w'] * (width * 2 + 1) for _ in range(height * 2 + 1)]
    stack = [(1, 1)]
    maze[1][1] = 'c'

    while stack:
        x, y = stack[-1]
        maze[y][x] = 'c'
        neighbors = []

        if x > 1 and maze[y][x - 2] == 'w':
            neighbors.append((x - 2, y))
        if x < width * 2 - 1 and maze[y][x + 2] == 'w':
            neighbors.append((x + 2, y))
        if y > 1 and maze[y - 2][x] == 'w':
            neighbors.append((x, y - 2))
        if y < height * 2 - 1 and maze[y + 2][x] == 'w':
            neighbors.append((x, y + 2))

        if neighbors:
            nx, ny = random.choice(neighbors)
            maze[(y + ny) // 2][(x + nx) // 2] = 'c'
            maze[ny][nx] = 'c'
            stack.append((nx, ny))
        else:
            stack.pop()

    return maze

def display_maze(maze):
    for row in maze:
        for cell in row:
            if cell == 'w':
                print(Fore.RED + cell + Style.RESET_ALL, end='')
            elif cell == 'c':
                print(Fore.GREEN + cell + Style.RESET_ALL, end='')
            elif cell == 'u':
                print(Fore.WHITE + cell + Style.RESET_ALL, end='')
        print()

def main():
    if len(sys.argv) > 1:
        try:
            width = int(sys.argv[1])
            height = int(sys.argv[2])
        except (ValueError, IndexError):
            print("Invalid arguments. Usage: python maze.py <width> <height>")
            sys.exit(1)
    else:
        while True:
            try:
                width = int(input("Enter the width of the maze (odd integer greater than 1): "))
                height = int(input("Enter the height of the maze (odd integer greater than 1): "))
                if width % 2 == 0 or height % 2 == 0 or width < 3 or height < 3:
                    raise ValueError
                break
            except ValueError:
                print("Invalid input. Please enter odd integers greater than 1.")

    maze = create_maze(width, height)
    display_maze(maze)

if __name__ == "__main__":
    main()
```

