from typing import List, Callable, Dict
from .voip_controller import VoIPController

class VoIPManager:
    def __init__(self):
        self.calls: Dict[int, VoIPController] = {}

    def start_call(self, call_id: int, endpoints: List[str], encryption_key: bytes, is_outgoing: bool):
        if not isinstance(call_id, int) or not isinstance(endpoints, list) or not isinstance(encryption_key, bytes):
            raise ValueError("Invalid input types")
        if not all(isinstance(endpoint, str) for endpoint in endpoints):
            raise ValueError("All endpoints must be strings")

        controller = VoIPController(call_id, endpoints, encryption_key, is_outgoing)
        self.calls[call_id] = controller
        controller.start()

    def end_call(self, call_id: int):
        if call_id not in self.calls:
            raise KeyError(f"No call with ID {call_id}")
        controller = self.calls.pop(call_id)
        controller.stop()

    def get_call_duration(self, call_id: int) -> float:
        if call_id not in self.calls:
            raise KeyError(f"No call with ID {call_id}")
        return self.calls[call_id].get_duration()

    def set_call_state_changed_handler(self, call_id: int, handler: Callable[[str], None]):
        if call_id not in self.calls:
            raise KeyError(f"No call with ID {call_id}")
        self.calls[call_id].set_state_changed_handler(handler)

    def set_call_audio_frame_handlers(self, call_id: int, send_handler: Callable[[int], bytes], recv_handler: Callable[[bytes], None]):
        if call_id not in self.calls:
            raise KeyError(f"No call with ID {call_id}")
        self.calls[call_id].set_audio_frame_handlers(send_handler, recv_handler)

