import mysql.connector
from mysql.connector import Error

class MysqlManager:
    def __init__(self, host, user, password):
        self.host = host
        self.user = user
        self.password = password
        self.connection = None
        self.cursor = None
        try:
            self.connection = mysql.connector.connect(
                host=self.host,
                user=self.user,
                password=self.password
            )
            self.cursor = self.connection.cursor()
        except Error as e:
            print(f"Error connecting to MySQL: {e}")

    def create_database(self, db_name):
        try:
            self.cursor.execute(f"SHOW DATABASES LIKE '{db_name}'")
            if self.cursor.fetchone() is None:
                self.cursor.execute(f"CREATE DATABASE {db_name}")
                print(f"Database '{db_name}' created.")
            else:
                print(f"Database '{db_name}' already exists.")
        except Error as e:
            print(f"Error creating database: {e}")

    def create_table(self, table_name, schema):
        try:
            self.cursor.execute(f"USE {self.connection.info['database']}")
            self.cursor.execute(f"CREATE TABLE {table_name} ({schema})")
            print(f"Table '{table_name}' created.")
        except Error as e:
            print(f"Error creating table: {e}")

    def insert(self, sql_command):
        try:
            self.cursor.execute(sql_command)
            self.connection.commit()
            print("Record inserted successfully.")
        except Error as e:
            print(f"Error inserting record: {e}")

    def commit(self):
        try:
            self.connection.commit()
            print("Transaction committed.")
        except Error as e:
            print(f"Error committing transaction: {e}")

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.cursor:
            self.cursor.close()
        if self.connection:
            self.connection.close()

# Example usage:
# manager = MysqlManager('localhost', 'user', 'password')
# manager.create_database('test_db')
