import re
from datetime import datetime

class DomainValidator:
    def __init__(self):
        self.domain_regex = re.compile(r"^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9][a-z0-9-]{0,61}[a-z0-9]$")
        self.ip_regex = re.compile(r"^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$")
        self.month_dict = {
            "01": "Jan", "02": "Feb", "03": "Mar", "04": "Apr", "05": "May", "06": "Jun",
            "07": "Jul", "08": "Aug", "09": "Sep", "10": "Oct", "11": "Nov", "12": "Dec"
        }

    def is_valid_domain(self, domain):
        return bool(self.domain_regex.match(domain))

    def is_valid_ip(self, ip):
        return bool(self.ip_regex.match(ip))

    def standardize_month(self, month):
        return self.month_dict.get(month, month)

    def pad_number(self, number):
        return f"{number:02d}"

    def format_date(self, date_str):
        try:
            date = datetime.strptime(date_str, "%d-%b-%Y")
            return date.strftime("%d-%b-%Y")
        except ValueError:
            return date_str
```

