import json
import sys
import os
from typing import List, Dict

def extract_data(file_path: str) -> List[Dict]:
    data = []
    with open(file_path, 'r') as file:
        for line in file:
            try:
                element = json.loads(line)
                data.append(element)
            except json.JSONDecodeError:
                print(f"Error decoding JSON in line: {line.strip()}")
    return data

def filter_elements(data: List[Dict], element_type: str) -> List[Dict]:
    return [element for element in data if element['type'] == element_type]

def extract_function_data(elements: List[Dict]) -> List[Dict]:
    return [{'name': element['name'],
             'signature': element['signature'],
             'doc': element['doc'],
             'params': element['params'],
             'template_args': element.get('template_args', [])}
            for element in elements if element['type'] == 'function']

def extract_define_data(elements: List[Dict]) -> List[Dict]:
    return [{'name': element['name'],
             'value': element['value'],
             'doc': element['doc']}
            for element in elements if element['type'] == 'define']

def extract_typedef_data(elements: List[Dict]) -> List[Dict]:
    return [{'name': element['name'],
             'value': element['value'],
             'doc': element['doc']}
            for element in elements if element['type'] == 'typedef']

def extract_enum_data(elements: List[Dict]) -> List[Dict]:
    return [{'name': element['name'],
             'doc': element['doc']}
            for element in elements if element['type'] == 'enumeration']

def extract_enum_member_data(elements: List[Dict]) -> List[Dict]:
    return [{'name': element['name'],
             'value': element['value'],
             'doc': element['doc']}
            for element in elements if element['type'] == 'enum_member']

def save_json(data: List[Dict], file_path: str):
    with open(file_path, 'w') as file:
        json.dump(data, file, indent=4)

def main(source: str, target_dir: str):
    if not os.path.exists(target_dir):
        os.makedirs(target_dir)

    data = extract_data(source)

    if not data:
        print("No valid data found in the input file.")
        return

    functions = extract_function_data(data)
    defines = extract_define_data(data)
    typedefs = extract_typedef_data(data)
    enumerations = extract_enum_data(data)
    enum_members = extract_enum_member_data(data)

    save_json(functions, os.path.join(target_dir, 'functions.json'))
    save_json(defines, os.path.join(target_dir, 'defines.json'))
    save_json(typedefs, os.path.join(target_dir, 'typedefs.json'))
    save_json(enumerations, os.path.join(target_dir, 'enumerations.json'))
    save_json(enum_members, os.path.join(target_dir, 'enum_members.json'))

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python script.py <source> <target-directory>")
        sys.exit(1)

    source = sys.argv[1]
    target_dir = sys.argv[2]

    main(source, target_dir)

