from flask import Flask, render_template, request, jsonify
from flask_socketio import SocketIO, emit
from threading import Lock

app = Flask(__name__)
app.config['SECRET_KEY'] = 'secret!'
socketio = SocketIO(app)

# Lock for thread-safe updates
vote_lock = Lock()

# Dictionary to store votes
votes = {'yes': 0, 'no': 0, 'maybe': 0}

def update_vote_totals(vote):
    """Update vote totals in a thread-safe manner."""
    with vote_lock:
        if vote in votes:
            votes[vote] += 1
        else:
            raise ValueError("Invalid vote")

@socketio.on('submit_vote')
def handle_submit_vote(data):
    """Handle vote submission and update totals."""
    vote = data['vote']
    try:
        update_vote_totals(vote)
        emit('update_totals', {'totals': votes}, broadcast=True)
    except ValueError as e:
        emit('error', {'message': str(e)}, broadcast=True)

@app.route('/')
def index():
    """Serve the HTML page with current vote totals."""
    return render_template('index.html', totals=votes)

if __name__ == '__main__':
    socketio.run(app, debug=True)
