import random

class Question:
    def __init__(self, question_text, correct_answer):
        self.question_text = question_text
        self.correct_answer = correct_answer

class Quiz:
    def __init__(self, quiz_data):
        self.questions = [Question(q['question'], q['correct_answer']) for q in quiz_data]
        self.current_question_index = 0
        self.score = 0

    def next_question(self):
        if self.current_question_index < len(self.questions):
            question = self.questions[self.current_question_index]
            self.current_question_index += 1
            return question
        else:
            return None

    def get_user_answer(self, question):
        while True:
            user_answer = input(question.question_text + " ").strip().lower()
            if user_answer in ['y', 'n', question.correct_answer.lower()]:
                return user_answer
            else:
                print("Invalid input. Please enter 'y', 'n', or the correct answer.")

    def check_answer(self, question, user_answer):
        if user_answer == question.correct_answer.lower():
            print("Correct!")
            self.score += 1
        else:
            print(f"Wrong! The correct answer is: {question.correct_answer}")

    def play(self):
        while True:
            question = self.next_question()
            if not question:
                break
            user_answer = self.get_user_answer(question)
            self.check_answer(question, user_answer)
            print(f"Your current score is: {self.score}/{len(self.questions)}")
        print(f"Quiz completed! Your final score is: {self.score}/{len(self.questions)}")

# Example quiz data
quiz_data = [
    {'question': 'Is Python an interpreted language?', 'correct_answer': 'y'},
    {'question': 'What is the capital of France?', 'correct_answer': 'n'},
    {'question': 'Is 2 + 2 equal to 5?', 'correct_answer': 'n'},
    {'question': 'What is the largest planet in our solar system?', 'correct_answer': 'y'}
]

# Initialize and run the quiz
