Here's a Python program using the Pygame library that implements the classic Snake game with the specified twists. The code includes the game loop, event handling, drawing functions, and additional features as requested.

```python
import pygame
import random
import sys

# Initialize Pygame
pygame.init()

# Constants
WIDTH, HEIGHT = 20, 20
GRID_SIZE = 10
SNAKE_SPEED = 10
FPS = 10

# Colors
WHITE = (255, 255, 255)
BLACK = (0, 0, 0)
GREEN = (0, 255, 0)
RED = (255, 0, 0)

# Game class
class SnakeGame:
    def __init__(self):
        self.screen = pygame.display.set_mode((WIDTH * GRID_SIZE, HEIGHT * GRID_SIZE))
        pygame.display.set_caption("Snake Game")
        self.clock = pygame.time.Clock()
        self.score = 0
        self.snake = [(WIDTH // 2, HEIGHT // 2)]
        self.direction = 'RIGHT'
        self.apple = self.spawn_apple()

    def spawn_apple(self):
        x, y = random.randint(0, WIDTH - 1), random.randint(0, HEIGHT - 1)
        while (x, y) in self.snake:
            x, y = random.randint(0, WIDTH - 1), random.randint(0, HEIGHT - 1)
        return (x * GRID_SIZE, y * GRID_SIZE)

    def move(self):
        head = self.snake[0]
        x, y = head
        if self.direction == 'UP':
            y -= GRID_SIZE
        elif self.direction == 'DOWN':
            y += GRID_SIZE
        elif self.direction == 'LEFT':
            x -= GRID_SIZE
        elif self.direction == 'RIGHT':
            x += GRID_SIZE

        self.snake.insert(0, (x, y))
        if x == self.apple[0] and y == self.apple[1]:
            self.score += 1
            self.apple = self.spawn_apple()
        else:
            self.snake.pop()

        # Check for collision with walls
        if x < 0 or x >= WIDTH or y < 0 or y >= HEIGHT:
            self.direction = ('RIGHT' if self.direction != 'LEFT' else 'DOWN') \
                           if self.direction in ('LEFT', 'UP') else ('LEFT' if self.direction != 'RIGHT' else 'UP')
            x, y = (x + GRID_SIZE) % WIDTH, (y + GRID_SIZE) % HEIGHT
            self.snake.insert(0, (x, y))

        # Check for collision with self
        if self.snake[0] in self.snake[1:]:
            sys.exit("Game Over!")

    def draw(self):
        self.screen.fill(WHITE)
        for segment in self.snake:
            pygame.draw.rect(self.screen, GREEN, pygame.Rect(segment[0] * GRID_SIZE, segment[1] * GRID_SIZE, GRID_SIZE, GRID_SIZE))
        pygame.draw.rect(self.screen, RED, pygame.Rect(self.apple[0], self.apple[1], GRID_SIZE, GRID_SIZE))
        font = pygame.font.Font(None, 36)
        text = font.render(f"Score: {self.score}", True, BLACK)
        self.screen.blit(text, (10, 10))
        pygame.display.flip()

    def handle_events(self):
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                sys.exit()
            elif event.type == pygame.KEYDOWN:
                if event.key == pygame.K_UP and self.direction != 'DOWN':
                    self.direction = 'UP'
                elif event.key == pygame.K_DOWN and self.direction != 'UP':
                    self.direction = 'DOWN'
                elif event.key == pygame.K_LEFT and self.direction != 'RIGHT':
                    self.direction = 'LEFT'
                elif event.key == pygame.K_RIGHT and self.direction != 'LEFT':
                    self.direction = 'RIGHT'

    def run(self):
        while True:
            self.handle_events()
            self.move()
            self.draw()
            self.clock.tick(FPS)

if __name__ == "__main__":
    game = SnakeGame()
    game.run()
```

