import subprocess
import sys

def run_command(command):
    """Run a command and return its output and return code."""
    process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
    output, error = process.communicate()
    return output.decode('utf-8'), process.returncode

def compare_outputs(rust_output, dotnet_output):
    """Compare the outputs of the Rust and .NET applications."""
    lines_rust = rust_output.splitlines()
    lines_dotnet = dotnet_output.splitlines()

    differences = []
    for line_rust, line_dotnet in zip(lines_rust, lines_dotnet):
        if line_rust != line_dotnet:
            differences.append((line_rust, line_dotnet))

    return differences

def print_differences(differences):
    """Print the differences between the outputs."""
    for line_rust, line_dotnet in differences:
        print(f"- {line_rust}")
        print(f"+ {line_dotnet}")

def main():
    try:
        rust_output, rust_returncode = run_command("cargo run --bin regex_rust")
        dotnet_output, dotnet_returncode = run_command("dotnet run --project regex_dotnet/regex_dotnet.csproj")

        if rust_returncode != 0 or dotnet_returncode != 0:
            print(f"Error: One or both applications failed to run.")
            if rust_returncode != 0:
                print(f"Rust application returned non-zero exit code: {rust_returncode}")
                print(f"Rust application stderr: {rust_output}")
            if dotnet_returncode != 0:
                print(f"DotNet application returned non-zero exit code: {dotnet_returncode}")
                print(f"DotNet application stderr: {dotnet_output}")
            sys.exit(1)

        differences = compare_outputs(rust_output, dotnet_output)
        if differences:
            print_differences(differences)
        else:
            print("No differences found between the outputs.")

    except Exception as e:
        print(f"An error occurred: {e}")
        sys.exit(1)

if __name__ == "__main__":
    main()

# Unit tests for compare_outputs function
def test_compare_outputs():
    assert compare_outputs("line1\nline2\nline3", "line1\nline2\nline4") == [("line3", "line4")]
    assert compare_outputs("line1\nline2\nline3", "line1\nline2\nline3") == []
    assert compare_outputs("line1\nline2\nline3", "line1\nline2\nline3\nline4") == [("line4", None)]
    assert compare_outputs("line1\nline2\nline3", "line1\nline2") == [("line3", None)]
    assert compare_outputs("line1\nline2\nline3", "line1\nline2\nline3\nline5") == [("line5", None)]

if __name__ == "__main__":
    test_compare_outputs()
```

