import re
import sys
from typing import List

def getCommon5() -> List[str]:
    with open('common5.txt', 'r') as file:
        return [line.strip() for line in file.readlines()]

def makePositionPattern(greenLetters: str) -> str:
    pattern = '^'
    for letter in greenLetters:
        pattern += f'[{letter}]'
    pattern += '$'
    return pattern

def makeNotPositionPattern(yellowLetters: str) -> str:
    pattern = '^'
    for letter in yellowLetters:
        pattern += f'(?!{letter})'
    pattern += '$'
    return pattern

def makeExcludePattern(badLetters: str) -> str:
    pattern = '^[^' + badLetters + ']*$'
    return pattern

def evaluateMatchingRules(word: str, greenLetters: str, yellowLetters: str, badLetters: str) -> bool:
    position_pattern = makePositionPattern(greenLetters)
    not_position_pattern = makeNotPositionPattern(yellowLetters)
    exclude_pattern = makeExcludePattern(badLetters)

    if re.match(position_pattern, word) and not re.match(not_position_pattern, word) and not re.match(exclude_pattern, word):
        return True
    return False

def printWords(commonWords: List[str], uncommonWords: List[str]):
    print("\nCommon Words:")
    for word in commonWords:
        print(word)
    print("\nUncommon Words:")
    for word in uncommonWords:
        print(word)

def runProcess():
    commonWords = getCommon5()
    comprehensiveWords = []
    with open('word-list-5.txt', 'r') as file:
        comprehensiveWords = [line.strip() for line in file.readlines()]

    greenLetters = ''
    yellowLetters = ''
    badLetters = ''

    for word in comprehensiveWords:
        if evaluateMatchingRules(word, greenLetters, yellowLetters, badLetters):
            if word in commonWords:
                commonWords.remove(word)
            else:
                uncommonWords.append(word)

    printWords(commonWords, uncommonWords)

def interview():
    while True:
        guess = input("Enter your guess (5 letters): ").lower()
        if len(guess) != 5 or not guess.isalpha():
            print("Invalid input. Please enter a 5-letter word.")
            continue
        break
    while True:
        green = input("Enter green letters (space-separated): ").lower().split()
        if len(green) != len(set(green)):
            print("Invalid input. Green letters must be unique.")
            continue
        break
    while True:
        yellow = input("Enter yellow letters (space-separated): ").lower().split()
        if len(yellow) != len(set(yellow)):
            print("Invalid input. Yellow letters must be unique.")
            continue
        break
    while True:
        bad = input("Enter bad letters (space-separated): ").lower().split()
        if len(bad) != len(set(bad)):
            print("Invalid input. Bad letters must be unique.")
            continue
        break

    global greenLetters, yellowLetters, badLetters
    greenLetters = ' '.join(green)
    yellowLetters = ' '.join(yellow)
    badLetters = ' '.join(bad)
    runProcess()

def main():
    sys.stdout.write("\033[2J\033[H")  # Clear the screen
    interview()

if __name__ == "__main__":
    main()
