    def get_package_path(self, name: str) -> str:
        return self.packages.get(name, None)

# Mock plugin system for demonstration purposes
class PluginSystem:
    def __init__(self):
        self.hooks = {
            'verify_package_hook': [],
            'config_hook': []
        }

    def register_hook(self, hook_name: str, hook_func: callable):
        self.hooks[hook_name].append(hook_func)

    def execute_hooks(self, *args, **kwargs):
        for hook_name, hook_list in self.hooks.items():
            for hook in hook_list:
                hook(*args, **kwargs)

# Puppet state file parser
def parse_puppet_state(file_path: str) -> Dict[str, Any]:
    if not os.path.exists(file_path) or not os.path.isfile(file_path):
        raise FileNotFoundError(f"Puppet state file not found at {file_path}")

    with open(file_path, 'r') as file:
        return yaml.safe_load(file)

# Verify package integrity hook
def verify_package_hook(package_name: str, package_path: str, puppet_state: Dict[str, Any]):
    if package_name in puppet_state:
        file_info = puppet_state[package_name]
        if 'checksums' in file_info:
            for checksum_type, checksum_value in file_info['checksums'].items():
                actual_checksum = self.get_file_checksum(package_path, checksum_type)
                if actual_checksum != checksum_value:
                    raise Exception(f"Checksum mismatch for {package_name} ({checksum_type}): expected {checksum_value}, got {actual_checksum}")

# Get file checksum
def get_file_checksum(file_path: str, checksum_type: str) -> str:
    hasher = getattr(hashlib, checksum_type)()
    with open(file_path, 'rb') as file:
        for chunk in iter(lambda: file.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

# Configuration hook to set Puppet state file path
def config_hook(config: Dict[str, Any]):
    config['puppet_state_file'] = config.get('puppet_state_file', 'puppet_state.yaml')

