    def get_holiday_by_id(self, id):
        for holiday in self.holidays:
            if holiday['id'] == id:
                return holiday
        return f"No holiday found with id: {id}"

class DeleteHolidayMixin:
    def delete_holiday_by_id(self, id):
        for holiday in self.holidays:
            if holiday['id'] == id:
                self.holidays.remove(holiday)
                return f"Holiday with id: {id} deleted successfully."
        return f"No holiday found with id: {id}"

class UpdateHolidayMixin:
    def update_holiday_by_id(self, id, new_data):
        for holiday in self.holidays:
            if holiday['id'] == id:
                if 'name' in new_data or 'date' in new_data:
                    holiday.update(new_data)
                    return f"Holiday with id: {id} updated successfully."
                else:
                    return "No changes to update."
