```python
import logging
import unittest

class Device:
    def __init__(self, name):
        self.name = name
        self.state = "OFF"

    def change_state(self, new_state):
        if new_state not in ["ON", "OFF"]:
            raise ValueError("Invalid state. Choose either 'ON' or 'OFF'.")
        self.state = new_state

    def get_state(self):
        return self.state


class Cover(Device):
    def __init__(self, name):
        super().__init__(name)

    def open(self):
        if self.state == "OFF":
            self.change_state("ON")
        else:
            self.change_state("OFF")

    def close(self):
        if self.state == "ON":
            self.change_state("OFF")
        else:
            self.change_state("ON")


class SmartHomeSystem:
    def __init__(self):
        self.devices = {}

    def add_device(self, device):
        self.devices[device.name] = device

    def toggle_device(self, device_name):
        device = self.devices.get(device_name)
        if device and device.state != "OFF":
            device.change_state("OFF")
        elif device and device.state == "OFF":
            device.change_state("ON")
        else:
            raise ValueError(f"Device '{device_name}' not found or unavailable.")

    def open_cover(self, cover_name):
        cover = self.devices.get(cover_name)
        if cover and cover.state == "OFF":
            cover.open()
        else:
            raise ValueError(f"Cover '{cover_name}' not found or unavailable.")

    def close_cover(self, cover_name):
        cover = self.devices.get(cover_name)
        if cover and cover.state == "ON":
            cover.close()
        else:
            raise ValueError(f"Cover '{cover_name}' not found or unavailable.")

    def turn_on_switch(self, switch_name):
        switch = self.devices.get(switch_name)
        if switch and switch.state == "OFF":
            switch.change_state("ON")
        else:
            raise ValueError(f"Switch '{switch_name}' not found or unavailable.")

    def turn_off_switch(self, switch_name):
        switch = self.devices.get(switch_name)
        if switch and switch.state == "ON":
            switch.change_state("OFF")
        else:
            raise ValueError(f"Switch '{switch_name}' not found or unavailable.")

    def get_device_state(self, device_name):
        device = self.devices.get(device_name)
        if device:
            return f"{device.name}: {device.state}"
        else:
            raise ValueError(f"Device '{device_name}' not found.")


class TestSmartHomeSystem(unittest.TestCase):
    def setUp(self):
        self.system = SmartHomeSystem()
        self.cover = Cover("Window Blinds")
        self.switch = Device("Living Room Light")
        self.system.add_device(self.cover)
        self.system.add_device(self.switch)

    def test_toggle_device(self):
