        self.system.open_cover("Window Blinds")
        self.assertEqual(self.cover.get_state(), "ON")
        self.system.close_cover("Window Blinds")
        self.assertEqual(self.cover.get_state(), "OFF")

    def test_close_cover(self):
        self.system.close_cover("Window Blinds")
        self.assertEqual(self.cover.get_state(), "OFF")
        self.system.open_cover("Window Blinds")
        self.assertEqual(self.cover.get_state(), "ON")

    def test_turn_on_switch(self):
        self.system.turn_on_switch("Living Room Light")
        self.assertEqual(self.switch.get_state(), "ON")
        self.system.turn_off_switch("Living Room Light")
        self.assertEqual(self.switch.get_state(), "OFF")

    def test_turn_off_switch(self):
        self.system.turn_off_switch("Living Room Light")
        self.assertEqual(self.switch.get_state(), "OFF")
        self.system.turn_on_switch("Living Room Light")
        self.assertEqual(self.switch.get_state(), "ON")

    def test_get_device_state(self):
