class Product:
    def __init__(self, name, quantity):
        self.name = name
        self.quantity = quantity

    def __str__(self):
        return f"{self.name} - Quantity: {self.quantity}"


class Store:
    def __init__(self):
        self.products = []

    def add_product(self, product):
        self.products.append(product)

    def display_products(self):
        if not self.products:
            print("No products available.")
        else:
            for product in self.products:
                print(product)

    def borrow_product(self, product_name):
        for product in self.products:
            if product.name == product_name and product.quantity > 0:
                product.quantity -= 1
                print(f"You have successfully borrowed {product.name}.")
                return
        print(f"Sorry, {product_name} is not available or out of stock.")

    def return_product(self, product_name):
        for product in self.products:
            if product.name == product_name:
                product.quantity += 1
                print(f"You have successfully returned {product.name}.")
                return
        print(f"Sorry, {product_name} is not in the inventory.")


class Buyer:
