def find_kth_largest(arr, k):
    if not arr:
        raise ValueError("The input list cannot be empty.")
    if k <= 0 or k > len(arr):
        raise ValueError("k must be a positive integer not exceeding the length of the list.")

    def bubble_sort(arr):
        n = len(arr)
        for i in range(n):
            for j in range(0, n - i - 1):
                if arr[j] > arr[j + 1]:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]

    bubble_sort(arr)
    return arr[len(arr) - k]
```

