```python
from ase import Atoms
import numpy as np

class ConfigMaker:
    def __init__(self):
        self.config_types = []
        self.lattice_vectors = None
        self.basis_atoms = None
        self.box_dimensions = None
        self.type_map = {}
        self.scale_factors = {}

        self.parse_configtypes()
        self.parse_config()

    def parse_configtypes(self):
        try:
            with open('CONFIGTYPES', 'r') as f:
                for line in f:
                    if line.strip():
                        self.config_types.append(line.strip())
        except FileNotFoundError:
            raise FileNotFoundError("CONFIGTYPES file not found.")
        except Exception as e:
            raise ValueError(f"Error parsing CONFIGTYPES: {e}")

    def parse_config(self):
        try:
            with open('LATVEC', 'r') as f:
                self.lattice_vectors = np.array([[float(x) for x in line.split()] for line in f])

            with open('BASIS', 'r') as f:
                self.basis_atoms = [line.strip().split() for line in f]

            with open('BOX', 'r') as f:
                self.box_dimensions = np.array([float(x) for x in f.readline().split()])

            with open('TYPEMAP', 'r') as f:
                for line in f:
                    if line.strip():
                        atom_type, element = line.strip().split()
                        self.type_map[atom_type] = element
                        self.scale_factors[atom_type] = float(self.config_types[self.type_map[atom_type]].split()[2])

        except FileNotFoundError:
            raise FileNotFoundError("One or more configuration files not found.")
        except Exception as e:
            raise ValueError(f"Error parsing configuration files: {e}")

    def add(self, symbols, positions, box):
        if len(symbols) != len(positions):
            raise ValueError("Number of symbols and positions must match.")

        atoms = Atoms(symbols, positions=positions, cell=box * self.scale_factors)
        self.atoms_list.append(atoms)

    def write_configs(self, filename):
        with open(filename, 'w') as f:
            for atoms in self.atoms_list:
                f.write(atoms.get_string())

# Example usage:
config_maker = ConfigMaker()
config_maker.add(['H', 'H'], [[0.0, 0.0, 0.0], [0.75, 0.75, 0.75]], np.eye(3) * 10.0)
config_maker.write_configs('output.xyz')
```

