from flask import Flask, render_template, request, jsonify
import multiprocessing
import json

app = Flask(__name__)

def load_dictionary(file_path):
    try:
        with open(file_path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return None

def genAcronym(words, clip, dictionary):
    acronyms = []
    for i in range(len(words)):
        for j in range(min(clip, len(words[i]))):
            acronym = words[i][:j+1]
            components = [(words[i], i)] * (j+1)
            processed_acronym = ''.join([word[0] if word[0] in dictionary else '?' for word in components])
            is_valid = all([word[0] in dictionary for word in components])
            acronyms.append((acronym, components, processed_acronym, is_valid))
    return acronyms

@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        phrase = request.form['phrase']
        clip = int(request.form['clip'])
        dictionary = load_dictionary('dictionary.json')

        if dictionary is None:
            return render_template('index.html', error='Dictionary file not found.')

        with multiprocessing.Pool() as pool:
            results = pool.apply_async(genAcronym, (phrase.split(), clip, dictionary)).get()

        return render_template('index.html', results=results, phrase=phrase, clip=clip)

    return render_template('index.html')

if __name__ == '__main__':
    app.run(debug=True)
