from enum import Enum
from typing import List, Dict, Any

class StacType(Enum):
    IMAGE = "image"
    VECTOR = "vector"
    GRID = "grid"

class GeeType(Enum):
    NONE = "None"
    EARTH_ENGINE_ASSET = "EarthEngineAsset"
    EARTH_ENGINE_COLLECTION = "EarthEngineCollection"
    EARTH_ENGINE_FEATURE_COLLECTION = "EarthEngineFeatureCollection"

class Issue:
    def __init__(self, message: str, severity: str, item: Any):
        self.message = message
        self.severity = severity
        self.item = item

def validate_stac_entries(stac_entries: List[Dict[str, Any]], non_commercial_ids: List[str]) -> List[Issue]:
    issues = []

    for entry in stac_entries:
        id_issue = check_id(entry)
        if id_issue:
            issues.append(id_issue)

        type_issue = check_type(entry)
        if type_issue:
            issues.append(type_issue)

        gee_type_issue = check_gee_type(entry)
        if gee_type_issue:
            issues.append(gee_type_issue)

        non_commercial_issue = check_non_commercial(entry, non_commercial_ids)
        if non_commercial_issue:
            issues.append(non_commercial_issue)

    return issues

def check_id(entry: Dict[str, Any]) -> Issue:
    if entry.get('id', '').startswith('UNKNOWN_ID'):
        return Issue(
            message="STAC entry has an UNKNOWN_ID",
            severity="error",
            item=entry
        )
    return None

def check_type(entry: Dict[str, Any]) -> Issue:
    valid_types = [stac_type.value for stac_type in StacType]
    if entry.get('type') not in valid_types:
        return Issue(
            message=f"STAC entry has invalid type: {entry.get('type')}",
            severity="error",
            item=entry
        )
    return None

def check_gee_type(entry: Dict[str, Any]) -> Issue:
    valid_gee_types = [gee_type.value for gee_type in GeeType]
    gee_type = entry.get('gee:type', GeeType.NONE.value)
    if gee_type not in valid_gee_types:
        return Issue(
            message=f"STAC entry has invalid gee:type: {gee_type}",
            severity="error",
            item=entry
        )
    return None

def check_non_commercial(entry: Dict[str, Any], non_commercial_ids: List[str]) -> Issue:
    dataset_id = entry.get('id')
    if dataset_id and dataset_id not in non_commercial_ids:
        return Issue(
            message=f"STAC entry with ID {dataset_id} is not in the non-commercial list",
            severity="warning",
            item=entry
        )
    return None

# Example usage:
stac_entries = [
    {"id": "UNKNOWN_ID123", "type": "image"},
    {"id": "valid_id", "type": "vector", "gee:type": "EarthEngineAsset"},
    {"id": "valid_id2", "type": "grid", "gee:type": "EarthEngineCollection"},
    {"id": "valid_id3", "type": "image", "gee:type": "InvalidType"},
    {"id": "valid_id4", "type": "vector"},
    {"id": "valid_id5", "type": "grid", "gee:type": "EarthEngineFeatureCollection"},
    {"id": "valid_id6", "type": "image", "gee:type": None},
    {"id": "valid_id7", "type": "vector", "gee:type": "EarthEngineAsset"},
    {"id": "valid_id8", "type": "grid", "gee:type": "EarthEngineCollection"},
    {"id": "valid_id9", "type": "image", "gee:type": None},
    {"id": "valid_id10", "type": "vector", "gee:type": "EarthEngineFeatureCollection"},
]

non_commercial_ids = ["valid_id1", "valid_id2"]

issues = validate_stac_entries(stac_entries, non_commercial_ids)
for issue in issues:
    print(f"{issue.severity.capitalize()}: {issue.message} - {issue.item['id']}")
