```python
import cv2
import mediapipe as mp

class EyeTracker:
    def __init__(self, frame_width, frame_height):
        self.frame_width = frame_width
        self.frame_height = frame_height
        self.mp_face_mesh = mp.solutions.face_mesh
        self.face_mesh = self.mp_face_mesh.FaceMesh(max_num_faces=1)
        self.eye_centers = []
        self.pupil_centers = []
        self.gaze_angles = []

    def detect_landmarks(self, frame):
        results = self.face_mesh.process(cv2.cvtColor(frame, cv2.COLOR_BGR2RGB))
        if results.multi_face_landmarks:
            for face_landmarks in results.multi_face_landmarks:
                self.draw_landmarks(frame, face_landmarks)
                self.calculate_gaze(face_landmarks)
        return frame

    def draw_landmarks(self, frame, landmarks):
        # Draw facial mesh, eyes, and pupils
        mp_drawing.draw_landmarks(frame, landmarks, mp.solutions.face_mesh.FACEMESH_CONTOURS)

    def calculate_gaze(self, landmarks):
        # Calculate eye and pupil centers, and gaze angle
        for id, left_eye in enumerate(landmarks.left_eyes):
            for i in range(len(left_eye)):
                self.eye_centers.append(left_eye[i].x * self.frame_width, left_eye[i].y * self.frame_height)

        for id, right_eye in enumerate(landmarks.right_eyes):
            for i in range(len(right_eye)):
                self.eye_centers.append(right_eye[i].x * self.frame_width, right_eye[i].y * self.frame_height)

        for id, pupil in enumerate(landmarks.left_pupils):
            self.pupil_centers.append(pupil.x * self.frame_width, pupil.y * self.frame_height)

        for id, pupil in enumerate(landmarks.right_pupils):
            self.pupil_centers.append(pupil.x * self.frame_width, pupil.y * self.frame_height)

        # Calculate gaze angle
        left_eye_center = self.eye_centers[2 * len(landmarks.left_eyes)]
        right_eye_center = self.eye_centers[2 * len(landmarks.right_eyes) - 1]
        gaze_vector = [right_eye_center[0] - left_eye_center[0], right_eye_center[1] - left_eye_center[1]]
        gaze_angle = np.arctan2(gaze_vector[1], gaze_vector[0]) * 180 / np.pi
        self.gaze_angles.append(gaze_angle)

    def visualize(self, frame):
        # Visualize eyes, pupils, and gaze direction
        for center in self.eye_centers:
            cv2.circle(frame, center, 5, (0, 255, 0), -1)

        for center in self.pupil_centers:
            cv2.circle(frame, center, 3, (0, 0, 255), -1)

        gaze_angle = self.gaze_angles[-1] if self.gaze_angles else 0
        gaze_vector = (self.eye_centers[-2][0] - self.eye_centers[-1][0], self.eye_centers[-2][1] - self.eye_centers[-1][1])
        length = np.sqrt(gaze_vector[0]**2 + gaze_vector[1]**2)
        gaze_vector = (gaze_vector[0] / length, gaze_vector[1] / length)
        p1 = (int(self.eye_centers[-1][0] + 10 * gaze_vector[0]), int(self.eye_centers[-1][1] + 10 * gaze_vector[1]))
        p2 = (int(self.eye_centers[-1][0] - 10 * gaze_vector[0]), int(self.eye_centers[-1][1] - 10 * gaze_vector[1]))
        cv2.arrowedLine(frame, p1, p2, (255, 0, 0), 2)

        return frame

    def process_frame(self, frame):
        self.detect_landmarks(frame)
        return self.visualize(frame)

    def handle_no_face(self):
        if not self.face_mesh.is_running():
            return True
        return False

# Test cases
if __name__ == "__main__":
    cap = cv2.VideoCapture(0)
    tracker = EyeTracker(cap.read()[1].shape[1], cap.read()[1].shape[0])

    while True:
        ret, frame = cap.read()
        if not ret:
            break

        if tracker.handle_no_face():
            print("No face detected. Exiting...")
            break

        frame = tracker.process_frame(frame)
        cv2.imshow("Eye Tracker", frame)

        if cv2.waitKey(1) & 0xFF == ord('q'):
            break

    cap.release()
    cv2.destroyAllWindows()
