# Import necessary Django modules and classes
from django.contrib.auth import login as auth_login
from django.contrib.auth.forms import UserCreationForm
from django.shortcuts import render, redirect
from django.urls import path
from django.contrib.auth.views import LoginView

# Custom Login View
class CustomLoginView(LoginView):
    template_name = 'login.html'
    redirect_authenticated_user = True

    def form_valid(self, form):
        auth_login(self.request, form.get_user())
        return super().form_valid(form)

# Registration View
class RegisterView(TemplateView):
    template_name = 'register.html'

    def get(self, request, *args, **kwargs):
        form = UserCreationForm()
        return render(request, self.template_name, {'form': form})

    def post(self, request, *args, **kwargs):
        form = UserCreationForm(request.POST)
        if form.is_valid():
            form.save()
            auth_login(request, form.get_user())
            return redirect('login')
        return render(request, self.template_name, {'form': form})

# URL patterns
urlpatterns = [
    path('', CustomLoginView.as_view(), name='login'),
    path('register/', RegisterView.as_view(), name='register'),
]

# Test cases
from django.test import TestCase, Client
from django.contrib.auth.models import User

class LoginTests(TestCase):
    def setUp(self):
        self.client = Client()
        self.user = User.objects.create_user(username='testuser', password='testpassword')

    def test_successful_login(self):
        response = self.client.post('/login/', {'username': 'testuser', 'password': 'testpassword'})
        self.assertRedirects(response, '/login/', fetch_redirect_response=False)
        self.assertTrue(self.client.session.get('django_session'))

    def test_unsuccessful_login(self):
        response = self.client.post('/login/', {'username': 'testuser', 'password': 'wrongpassword'})
        self.assertFormError(response, 'form', 'password', 'Incorrect password.')

class RegisterTests(TestCase):
    def setUp(self):
        self.client = Client()

    def test_successful_registration(self):
        response = self.client.post('/register/', {'username': 'newuser', 'password1': 'newpassword', 'password2': 'newpassword'})
        self.assertRedirects(response, '/login/', fetch_redirect_response=False)
        self.assertTrue(User.objects.filter(username='newuser').exists())

    def test_unsuccessful_registration(self):
        response = self.client.post('/register/', {'username': 'newuser', 'password1': 'short', 'password2': 'short'})
        self.assertFormError(response, 'form', 'password1', 'Enter the same password again.')
