```python
import argparse
import os

def load_tasks():
    if not os.path.exists('todo.txt'):
        return []
    with open('todo.txt', 'r') as file:
        tasks = [line.strip() for line in file.readlines()]
    return tasks

def save_tasks(tasks):
    with open('todo.txt', 'w') as file:
        for i, task in enumerate(tasks, start=1):
            file.write(f"{'[x]' if task.startswith('[x]') else '[ ]'} {task}\n")

def add_task(tasks, description):
    tasks.append(f"[ ] {description}")
    save_tasks(tasks)

def list_tasks(tasks):
    if not tasks:
        print("No tasks found.")
        return
    for i, task in enumerate(tasks, start=1):
        print(f"{i}. {task}")

def mark_task_done(tasks, task_number):
    if 1 <= task_number <= len(tasks):
        tasks[task_number - 1] = tasks[task_number - 1].replace('[ ', '[x ']
        save_tasks(tasks)
    else:
        print("Invalid task number.")

def main():
    parser = argparse.ArgumentParser(description="Simple To-Do list manager.")
    subparsers = parser.add_subparsers(dest="command")

    add_parser = subparsers.add_parser("add", help="Add a new task.")
    add_parser.add_argument("description", help="Task description")

    list_parser = subparsers.add_parser("list", help="List all tasks.")

    done_parser = subparsers.add_parser("done", help="Mark a task as done.")
    done_parser.add_argument("task_number", type=int, help="Task number")

    args = parser.parse_args()

    tasks = load_tasks()

    if args.command == "add":
        add_task(tasks, args.description)
    elif args.command == "list":
        list_tasks(tasks)
    elif args.command == "done":
        mark_task_done(tasks, args.task_number)

if __name__ == "__main__":
    main()
```

