```python
import tkinter as tk
import random

class Blackjack:
    def __init__(self, master):
        self.master = master
        master.title("Blackjack")

        self.score_player = 0
        self.score_dealer = 0
        self.deck = self.create_deck()
        self.shuffle_deck()

        self.create_widgets()

    def create_deck(self):
        suits = ["Hearts", "Diamonds", "Clubs", "Spades"]
        values = [2, 3, 4, 5, 6, 7, 8, 9, 10, 10, 10, 10, 11]
        deck = [(value, suit) for suit in suits for value in values]
        return deck

    def shuffle_deck(self):
        random.shuffle(self.deck)

    def deal_card(self):
        return self.deck.pop()

    def calculate_score(self, hand):
        score = 0
        aces = 0
        for card in hand:
            if card[0] == 11 and aces > 0:
                score += 10
            elif card[0] == 1:
                score += 11
                aces += 1
            else:
                score += card[0]
        while score > 21 and aces > 0:
            score -= 10
            aces -= 1
        return score

    def play_game(self):
        self.player_hand = [self.deal_card(), self.deal_card()]
        self.dealer_hand = [self.deal_card(), self.deal_card()]

        self.update_score_display()

        while True:
            if self.player_score() < 17:
                action = self.get_player_action()
                if action == "Hit":
                    self.player_hand.append(self.deal_card())
                    self.update_score_display()
                elif action == "Stand":
                    break
            else:
                break

        self.dealer_hand.append(self.deal_card())
        self.dealer_hand.append(self.deal_card())

        while self.dealer_score() < 17:
            self.dealer_hand.append(self.deal_card())

        self.update_score_display()
        self.declare_winner()

    def player_score(self):
        return self.calculate_score(self.player_hand)

    def dealer_score(self):
        return self.calculate_score(self.dealer_hand)

    def get_player_action(self):
        action = self.action_button.get()
        if action in ["Hit", "Stand"]:
            return action
        else:
            return self.get_player_action()

    def update_score_display(self):
        self.player_label.config(text=f"Player: {self.player_score()}")
        self.dealer_label.config(text=f"Dealer: {self.dealer_score()}")

    def declare_winner(self):
        if self.player_score() > self.dealer_score():
            self.winner_label.config(text="You win!")
            self.score_player += 1
        elif self.player_score() < self.dealer_score():
            self.winner_label.config(text="Dealer wins!")
            self.score_dealer += 1
        else:
            self.winner_label.config(text="It's a tie!")

    def create_widgets(self):
        self.frame = tk.Frame(self.master)
        self.frame.pack(pady=20)

        self.player_label = tk.Label(self.frame, text=f"Player: {self.player_score()}")
        self.player_label.grid(row=0, column=0)

        self.dealer_label = tk.Label(self.frame, text=f"Dealer: {self.dealer_score()}")
        self.dealer_label.grid(row=0, column=1)

        self.player_hand_display = tk.Listbox(self.frame, width=15, height=2)
        self.player_hand_display.grid(row=1, column=0)
        for card in self.player_hand:
            self.player_hand_display.insert(tk.END, f"{card[0]} of {card[1]}")

        self.dealer_hand_display = tk.Listbox(self.frame, width=15, height=2)
        self.dealer_hand_display.grid(row=1, column=1)
        for card in self.dealer_hand:
            self.dealer_hand_display.insert(tk.END, f"{card[0]} of {card[1]}")

        self.action_button = tk.Button(self.frame, text="Hit", command=self.play_game)
        self.action_button.grid(row=2, column=0)

        self.stand_button = tk.Button(self.frame, text="Stand", command=self.play_game)
        self.stand_button.grid(row=2, column=1)

        self.winner_label = tk.Label(self.frame, text="")
        self.winner_label.grid(row=3, columnspan=2)

if __name__ == "__main__":
    root = tk.Tk()
    game = Blackjack(root)
    root.mainloop()
```

