```python
import random

class Gem:
    def __init__(self, color):
        self.color = color

    def __repr__(self):
        return f"Gem({self.color})"

class Grid:
    def __init__(self, size=8):
        self.size = size
        self.grid = [[Gem(random.choice(['R', 'B', 'G', 'Y'])) for _ in range(size)] for _ in range(size)]
        self.score = 0

    def swap(self, x1, y1, x2, y2):
        if x1 == x2 and y1 != y2:  # horizontal swap
            self.grid[x1][y1], self.grid[x2][y1] = self.grid[x2][y1], self.grid[x1][y1]
        elif y1 == y2 and x1 != x2:  # vertical swap
            self.grid[x1][y1], self.grid[x1][y2] = self.grid[x1][y2], self.grid[x1][y1]
        else:
            raise ValueError("Invalid swap")

    def check_matches(self):
        matches = []
        for x in range(self.size):
            for y in range(self.size - 2):
                if self.grid[x][y] and self.grid[x][y] == self.grid[x][y + 1] == self.grid[x][y + 2]:
                    matches.append((x, y))
        return matches

    def remove_matches(self, matches):
        for x, y in matches:
            self.grid[x][y] = None
            self.grid[x][y + 1] = None
            self.grid[x][y + 2] = None
            self.score += 1

    def fall_gems(self):
        for x in range(self.size):
            empty_rows = [y for y in range(self.size) if self.grid[x][y] is None]
            for y in reversed(empty_rows):
                self.grid[x][y] = self.grid[x][y - 1]
                self.grid[x][y - 1] = None

    def reshuffle(self):
        for x in range(self.size):
            for y in range(self.size):
                if self.grid[x][y] is None:
                    self.grid[x][y] = Gem(random.choice(['R', 'B', 'G', 'Y']))

    def is_game_over(self):
        for x in range(self.size):
            for y in range(self.size):
                if self.grid[x][y] is not None:
                    return False
        return True

def main():
    grid = Grid()
    while not grid.is_game_over():
        print(grid)
        x1, y1 = map(int, input("Enter coordinates for the first gem (x1 y1): ").split())
        x2, y2 = map(int, input("Enter coordinates for the second gem (x2 y2): ").split())
        try:
            grid.swap(x1, y1, x2, y2)
            matches = grid.check_matches()
            if matches:
                grid.remove_matches(matches)
                grid.fall_gems()
            else:
                print("No matches found.")
        except ValueError as e:
            print(e)
        if grid.is_game_over():
            print("Game Over! Your score is:", grid.score)
            grid.reshuffle()

if __name__ == "__main__":
    main()
