                    'created_at': datetime.strptime(tweet_data['created_at'], '%Y-%m-%dT%H:%M:%S'),
                    'user_id': tweet_data['user_id']
                }
                tweets[tweet_id] = tweet
            except (KeyError, ValueError) as e:
