from datetime import datetime
from typing import Dict, Any

class Tweet:
    def __init__(self, id: str, text: str, created_at: str, user_id: str):
        self.id = id
        self.text = text
        self.created_at = datetime.fromisoformat(created_at)
        self.user_id = user_id

    def to_dict(self) -> Dict[str, Any]:
        return {
            'text': self.text,
            'created_at': self.created_at.isoformat(),
            'user_id': self.user_id
        }

class Tweets:
    @classmethod
    def from_dict(cls, tweets_dict: Dict[str, Dict[str, Any]]) -> 'Tweets':
        tweets = []
        for tweet_id, tweet_data in tweets_dict.items():
            try:
                text = tweet_data['text']
                created_at = datetime.fromisoformat(tweet_data['created_at'])
                user_id = tweet_data['user_id']
            except (KeyError, ValueError) as e:
                raise ValueError(f"Invalid tweet data for ID {tweet_id}: {e}")

            if not text:
                raise ValueError(f"Tweet text for ID {tweet_id} cannot be empty")

            tweet = Tweet(tweet_id, text, created_at, user_id)
            tweets.append(tweet)

        return cls(tweets)

    def to_dict(self) -> Dict[str, Dict[str, Any]]:
        return {tweet.id: tweet.to_dict() for tweet in self.tweets}

    @property
    def tweets(self) -> list:
        return self._tweets

    @tweets.setter
    def tweets(self, value: list):
        self._tweets = value

# Example usage:
