        self.assertFalse(open_account('1234567', 'John Doe', '1000.00', '5000.00'))  # Invalid account number
        self.assertFalse(open_account('12345678', '', '1000.00', '5000.00'))  # Invalid account holder's name
        self.assertFalse(open_account('12345678', 'John Doe', '-1000.00', '5000.00'))  # Invalid initial deposit

if __name__ == '__main__':
