        if self.gpp_type == 'spp':
            return self._spatial_pyramid_pooling(x, mask)
        elif self.gpp_type == 'tpp':
            return self._temporal_pyramid_pooling(x, mask)
        elif self.gpp_type == 'gpp':
            return self._generic_pyramid_pooling(x, mask)

    def _spatial_pyramid_pooling(self, x, mask):
        if mask is not None:
            x = x * mask
        pooled_features = []
        for level in self.levels:
            pool_output = F.adaptive_max_pool2d(x, (level, level)) if self.pool_type == 'max_pool' else F.adaptive_avg_pool2d(x, (level, level))
            pooled_features.append(pool_output)
        return torch.cat(pooled_features, dim=1)

    def _temporal_pyramid_pooling(self, x, mask):
        if mask is not None:
            x = x * mask
        pooled_features = []
        for level in self.levels:
            pool_output = F.adaptive_max_pool2d(x, (1, level)) if self.pool_type == 'max_pool' else F.adaptive_avg_pool2d(x, (1, level))
            pooled_features.append(pool_output)
        return torch.cat(pooled_features, dim=1)

    def _generic_pyramid_pooling(self, x, mask):
        if mask is not None:
            x = x * mask
        level1_features, level2_features = self.levels
        pool_output1 = F.adaptive_max_pool2d(x, (level1_features, level1_features)) if self.pool_type == 'max_pool' else F.adaptive_avg_pool2d(x, (level1_features, level1_features))
        pool_output2 = F.adaptive_max_pool2d(x, (level2_features, level2_features)) if self.pool_type == 'max_pool' else F.adaptive_avg_pool2d(x, (level2_features, level2_features))
        return torch.cat([pool_output1, pool_output2], dim=1)

