import socket
import threading

class ChatClient:
    def __init__(self, host, port):
        self.host = host
        self.port = port
        self.nickname = None
        self.sock = None
        self.receive_thread = None
        self.send_thread = None

    def get_nickname(self):
        while True:
            self.nickname = input("Enter your nickname: ")
            if self.nickname:
                break
            else:
                print("Nickname cannot be empty. Please try again.")
        return self.nickname

    def connect(self):
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.connect((self.host, self.port))
        print("Connected to the server.")
        self.send_nickname()
        self.start_threads()

    def send_nickname(self):
        self.sock.sendall(self.nickname.encode())
        response = self.sock.recv(1024).decode()
        if response == "NICK":
            print("Nickname accepted by the server.")
        else:
            print("Failed to set nickname. Server response:", response)

    def start_threads(self):
        self.receive_thread = threading.Thread(target=self.receive_messages)
        self.send_thread = threading.Thread(target=self.send_messages)
        self.receive_thread.start()
        self.send_thread.start()

    def receive_messages(self):
        while True:
            try:
                message = self.sock.recv(1024).decode()
                if message == "DISCONNECT":
                    break
                print(f"Received: {message}")
            except socket.error as e:
                print(f"Error receiving message: {e}")
                break

    def send_messages(self):
        while True:
            message = input("Enter your message: ")
            if message.lower() == "disconnect":
                self.sock.sendall("DISCONNECT".encode())
                break
            self.sock.sendall(message.encode())

    def close(self):
        self.sock.close()
        print("Disconnected from the server.")

if __name__ == "__main__":
    host = "localhost"
    port = 12345
    client = ChatClient(host, port)
    nickname = client.get_nickname()
    client.connect()
