```python
import os
import subprocess

class LaTeXDocument:
    def __init__(self, filename, documentclass='article', options=None):
        self.filename = filename
        self.documentclass = documentclass
        self.options = options or {}
        self.content = []
        self.metadata = {'title': None, 'author': None, 'date': None}
        self.packages = []

    def add_section(self, title, label=None):
        self.content.append(f'\\section*{{{title}}}\n')
        if label:
            self.content.append(f'\\label{{sec:{label}}}\n')

    def add_subsection(self, title, label=None):
        self.content.append(f'\\subsection*{{{title}}}\n')
        if label:
            self.content.append(f'\\label{{subsec:{label}}}\n')

    def add_paragraph(self, text):
        self.content.append(f'\\paragraph*{{{text}}}\n')

    def add_bullet_points(self, items):
        self.content.append('\\begin{itemize}\n')
        for item in items:
            self.content.append(f'  \\item {item}\n')
        self.content.append('\\end{itemize}\n')

    def add_equation(self, equation, label=None):
        self.content.append(f'\\begin{{equation}}\n')
        self.content.append(f'  {equation}\n')
        if label:
            self.content.append(f'  \\label{{eq:{label}}}\n')
        self.content.append('\\end{equation}\n')

    def add_image(self, filepath, options=None):
        options = options or {}
        self.content.append(f'\\begin{{figure}}[htbp]\n')
        self.content.append(f'  \\centering\n')
        self.content.append(f'  \\includegraphics[width=\\linewidth]{{{filepath}}}\n')
        for key, value in options.items():
            self.content.append(f'  {key} = {value}\n')
        self.content.append('  \\caption{{}}\\label{{fig:{os.path.basename(filepath)}}}\n')
        self.content.append('\\end{figure}\n')

    def add_table(self, data, column_format, caption=None, label=None):
        self.content.append(f'\\begin{{table}}[htbp]\n')
        self.content.append(f'  \\centering\n')
        self.content.append(f'  \\begin{{tabular}}{{{column_format}}}\n')
        self.content.append('    \\toprule\n')
        for row in data:
            self.content.append('    ' + ' & '.join(row) + ' \\\\\n')
        self.content.append('    \\bottomrule\n')
        if caption:
            self.content.append(f'  \\caption{{{caption}}}\n')
        if label:
            self.content.append(f'  \\label{{tab:{label}}}\n')
        self.content.append('  \\end{{tabular}}\n')
        self.content.append('  \\label{{tab:{os.path.basename(self.filename)}}}\n')
        self.content.append('\\end{table}\n')

    def set_metadata(self, title=None, author=None, date=None):
        if title:
            self.metadata['title'] = title
        if author:
            self.metadata['author'] = author
        if date:
            self.metadata['date'] = date

    def compile(self):
        with open(self.filename, 'w') as file:
            file.write(self.generate_latex_code())
        self.run_latex(self.filename)

    def generate_latex_code(self):
        latex_code = [
            f'documentclass[{", ".join(self.options.keys())}]{{{self.documentclass}}}\n',
            f'\\usepackage{{graphicx}}\n',
            f'\\usepackage{{booktabs}}\n',
            f'\\usepackage{{amsmath}}\n',
            f'\\title{{{self.metadata.get("title", "Untitled")}}}\n',
            f'\\author{{{self.metadata.get("author", "Unknown")}}}\n',
            f'\\date{{{self.metadata.get("date", "Today")}}}\n',
            '\\begin{document}\n',
            '\\maketitle\n',
            '\\tableofcontents\n',
            '\\newpage\n',
            '\n'.join(self.content),
            '\\end{document}\n'
        ]
        for package in self.packages:
            latex_code.append(f'\\usepackage{{{package}}}\n')
        return '\n'.join(latex_code)

    def run_latex(self, filename):
        try:
            subprocess.run(['pdflatex', filename], check=True)
        except subprocess.CalledProcessError as e:
            print(f"Error compiling LaTeX document: {e}")

# Example usage:
doc = LaTeXDocument('example.tex')
doc.set_metadata(title='Example Document', author='John Doe', date='2023-04-01')
doc.add_section('Introduction', 'intro')
doc.add_subsection('Background', 'bg')
doc.add_paragraph('This is a paragraph of text.')
doc.add_bullet_points(['Item 1', 'Item 2', 'Item 3'])
doc.add_equation(r'E = mc^2', 'eq:einstein')
doc.add_image('path/to/image.png', {'width': '\\textwidth'})
doc.add_table([
    ['Header 1', 'Header 2'],
    ['Row 1, Col 1', 'Row 1, Col 2'],
    ['Row 2, Col 1', 'Row 2, Col 2']
], 'll', 'A sample table', 'tab:sample')
doc.compile()
```

