```python
import requests
from bs4 import BeautifulSoup

class TCPclient:
    def __init__(self):
        self.input_data = ""

    def send(self, data):
        self.input_data = data

    def receive(self):
        return self.input_data

def isValid(text):
    return "wikipedia" in text.lower()

def handle(search_term, client):
    if not isValid(search_term):
        client.send("Invalid input. Please say 'Wikipedia' followed by your search term.")
        return

    search_term = search_term.replace("wikipedia", "").strip()

    if not search_term:
        client.send("Please provide a search term after saying 'Wikipedia'.")
        return

    try:
        url = f"https://en.wikipedia.org/w/api.php?action=query&format=json&prop=extracts&exintro=1&explaintext=1&titles={search_term}"
        response = requests.get(url)
        data = response.json()

        pages = data["query"]["pages"]
        if search_term in pages:
            page_id = list(pages.keys())[0]
            extract = pages[page_id]["extract"]
            client.send(extract[:extract.find(". ")])
        else:
            client.send("No Wikipedia page found for the given search term.")
    except Exception as e:
        client.send(f"An error occurred: {str(e)}")

def main():
    client = TCPclient()

    print("Wikipedia search assistant. Say 'Wikipedia' followed by your search term.")
    while True:
        user_input = input("You: ")
        client.send(user_input)

        response = client.receive()
        print("Assistant:", response)

        if "Wikipedia" in response:
            search_term = response.split()[-1]
            handle(search_term, client)

if __name__ == "__main__":
    main()
```

