import csv
import random
import webbrowser

def create_hexagram():
    hexagram = [0] * 6
    for _ in range(6):
        hexagram.append(random.choice([0, 1]))
    return ''.join(map(str, hexagram))

def read_iching_dict(filename):
    iching_dict = {}
    try:
        with open(filename, newline='') as csvfile:
            reader = csv.reader(csvfile)
            next(reader)  # Skip header
            for row in reader:
                iching_dict[row[0]] = {
                    'hexagram_number': int(row[1]),
                    'hexagram_name': row[2],
                    'hexagram_description': row[3]
                }
    except FileNotFoundError:
        print(f"Error: The file {filename} was not found.")
    except Exception as e:
        print(f"Error reading the file {filename}: {e}")
    return iching_dict

def main():
    filename = 'ichingdict.csv'
    iching_dict = read_iching_dict(filename)

    if not iching_dict:
        return

    hexagram = create_hexagram()
    print(f"Hexagram: {hexagram}")

    if hexagram in iching_dict:
        hexagram_info = iching_dict[hexagram]
        print(f"Hexagram Number: {hexagram_info['hexagram_number']}")
        print(f"Hexagram Name: {hexagram_info['hexagram_name']}")
        print(f"Hexagram Description: {hexagram_info['hexagram_description']}")

        more_info = input("Would you like to open a webpage with more information about this hexagram? (y/n): ").strip().lower()
        if more_info == 'y':
            url = f"https://www.usf.edu/cas/anthropology/iching/hexagram{hexagram_info['hexagram_number']}.html"
            webbrowser.open(url)
        elif more_info == 'n':
            print("Exiting the program.")
        else:
            print("Invalid input. Exiting the program.")
    else:
        print("Hexagram not found in the dictionary.")

if __name__ == "__main__":
    main()
