import re

def find_extremes(numbers):
    if not numbers:
        return (None, None)
    min_val = max_val = numbers[0]
    for num in numbers[1:]:
        if num < min_val:
            min_val = num
        elif num > max_val:
            max_val = num
    return (min_val, max_val)

def is_palindrome(s):
    if not isinstance(s, str):
        return False
    s = re.sub(r'\W+', '', s.lower())  # Remove non-alphanumeric characters and convert to lowercase
    if len(s) <= 1:
        return True
    else:
        return s[0] == s[-1] and is_palindrome(s[1:-1])  # Recursive call
