import torch
import torch.nn as nn
from torchvision import models

class DenseNetEncoder(nn.Module):
    def __init__(self, num_classes=1000):
        super(DenseNetEncoder, self).__init__()
        self.model = models.densenet121(pretrained=False)
        self.model.classifier = nn.Identity()

    def forward(self, x):
        return self.model(x)

class ResNetEncoder(nn.Module):
    def __init__(self, num_classes=1000):
        super(ResNetEncoder, self).__init__()
        self.model = models.resnet50(pretrained=False)
        self.model.fc = nn.Identity()

    def forward(self, x):
        return self.model(x)

class FeatureExtractor:
    def __init__(self, architecture='densenet', pretrained=True):
        if architecture not in ['densenet', 'resnet']:
            raise ValueError("Unsupported architecture. Choose either 'densenet' or 'resnet'.")

        if architecture == 'densenet':
            self.encoder = DenseNetEncoder(pretrained=pretrained)
        else:
            self.encoder = ResNetEncoder(pretrained=pretrained)

    def extract_features(self, images):
        if not isinstance(images, torch.Tensor):
            images = torch.tensor(images, dtype=torch.float32)

        if images.ndimension() != 4:
            raise ValueError("Input images must be a 4D tensor (batch_size, channels, height, width).")

        # Normalize images if required by the model
        if self.encoder.model.name == 'densenet121':
            images = images / 255.0
            images = (images - 0.5) * 2.0
        elif self.encoder.model.name == 'resnet50':
            images = images / 255.0
            images = (images - 0.5) * 2.0

        # Extract features
        features = {}
        for name, layer in self.encoder.model.features.named_children():
            features[name] = layer(images)

        return features

