```python
import numpy as np

class Quixo:
    def __init__(self):
        self.board = np.zeros((5, 5), dtype=int)
        self.initialize_board()

    def initialize_board(self):
        for i in range(5):
            for j in range(5):
                self.board[i, j] = (i * 5) + j + 1

    def print_board(self):
        for row in self.board:
            print(" ".join(str(x) for x in row))

    def is_valid_move(self, piece, target):
        if not (0 <= target[0] < 5 and 0 <= target[1] < 5):
            return False
        if self.board[target] != 0:
            return False
        if piece not in [1, 2, 3, 4, 5, 6, 7, 8, 9]:
            return False
        return True

    def make_move(self, piece, target):
        if self.is_valid_move(piece, target):
            self.board[target] = piece
            return True
        return False

    def check_win(self, player):
        # Check horizontal, vertical, and diagonal lines for a win
        for i in range(5):
            for j in range(5):
                if np.all(self.board[i, j:j+4] == player) or np.all(self.board[i:i+4, j] == player):
                    return True
        if np.all(np.diag(self.board) == player) or np.all(np.diag(np.fliplr(self.board)) == player):
            return True
        return False

    def alpha_beta_pruning(self, depth, alpha, beta, maximizing_player):
        if depth == 0 or self.check_win(1):
            return self.evaluate_board(1)
        if maximizing_player:
            max_eval = float('-inf')
            for piece in range(1, 10):
                for target in self.get_possible_moves(piece):
                    self.make_move(piece, target)
                    eval = self.alpha_beta_pruning(depth - 1, alpha, beta, False)
                    self.board[target[0], target[1]] = 0
                    max_eval = max(max_eval, eval)
                    alpha = max(alpha, eval)
                    if beta <= alpha:
                        break
            return max_eval
        else:
            min_eval = float('inf')
            for piece in range(1, 10):
                for target in self.get_possible_moves(piece):
                    self.make_move(piece, target)
                    eval = self.alpha_beta_pruning(depth - 1, alpha, beta, True)
                    self.board[target[0], target[1]] = 0
                    min_eval = min(min_eval, eval)
                    beta = min(beta, eval)
                    if beta <= alpha:
                        break
            return min_eval

    def get_possible_moves(self, piece):
        moves = []
        for i in range(5):
            if piece in [1, 2, 3, 4]:
                for j in range(5):
                    if self.board[i, j] == 0:
                        moves.append((i, j))
            elif piece in [5, 6, 7, 8]:
                for j in range(5):
                    if self.board[j, 4 - i] == 0:
                        moves.append((4 - j, i))
        return moves

    def evaluate_board(self, player):
        score = 0
        for i in range(5):
            for j in range(5):
                if self.board[i, j] == player:
                    score += 1
        return score - (55 - score)

    def play(self):
        current_player = 1
        while True:
            self.print_board()
            if current_player == 1:
                piece = int(input("Enter the piece to move (1-9): "))
                target = tuple(map(int, input("Enter the target position (x y): ").split()))
                if self.make_move(piece, target):
                    if self.check_win(current_player):
                        self.print_board()
                        print(f"Player {current_player} wins!")
                        return
                    current_player = 2
                else:
                    print("Invalid move. Try again.")
            else:
                possible_moves = self.get_possible_moves(current_player)
                best_move = max(possible_moves, key=lambda move: self.alpha_beta_pruning(3, float('-inf'), float('inf'), True))
                self.make_move(current_player, best_move)
                if self.check_win(current_player):
                    self.print_board()
                    print(f"AI (Player {current_player}) wins!")
                    return
            current_player *= -1

if __name__ == "__main__":
    game = Quixo()
    game.play()
```

