import numpy as np

def calculate_determinant(n):
    # Initialize the adjacency matrix
    A = np.zeros((n, n), dtype=int)

    # Set diagonal entries to 3
    for i in range(n):
        A[i][i] = 3

    # Set entries corresponding to edges to -1
    for i in range(n-1):
        A[i][i+1] = A[i+1][i] = -1

    # Set the last edge to complete the cycle
    A[0][n-1] = A[n-1][0] = -1

    # Perform Gaussian elimination without pivoting
    for i in range(n):
        # Find the pivot row
        pivot_row = i
        while A[pivot_row][i] == 0:
            pivot_row += 1
            if pivot_row == n:
                return 0  # The matrix is singular

        # Swap rows if necessary
        if pivot_row != i:
            A[[i, pivot_row]] = A[[pivot_row, i]]

        # Eliminate entries below the pivot
        for j in range(i+1, n):
            factor = A[j][i] / A[i][i]
            A[j][i:] -= factor * A[i][i:]

    # The determinant is the product of the diagonal entries
    determinant = 1
    for i in range(n):
        determinant *= A[i][i]

    return determinant

def main():
    while True:
        try:
            n = int(input("Enter a positive integer for the number of vertices (n): "))
            if n < 1:
                print("Error: n must be a positive integer.")
            else:
                break
        except ValueError:
            print("Error: Please enter a valid positive integer.")

    determinant = calculate_determinant(n)
    print(f"The determinant of the circular adjacency matrix for a cycle graph with {n} vertices is: {determinant}")

if __name__ == "__main__":
    main()
