from flask import Flask, request, jsonify
from flask_marshmallow import Marshmallow
import uuid

app = Flask(__name__)
ma = Marshmallow(app)

# Define the Product schema
class ProductSchema(ma.Schema):
    class Meta:
        fields = ('id', 'name', 'quantity')

product_schema = ProductSchema()
products_schema = ProductSchema(many=True)

# In-memory storage for products
products = {}

# List all products
@app.route('/products', methods=['GET'])
def get_products():
    """
    List all products in the inventory.
    """
    return products_schema.jsonify(products.values())

# Get a single product
@app.route('/products/<id>', methods=['GET'])
def get_product(id):
    """
    Retrieve details of a specific product by its id.
    """
    product = products.get(id)
    if product is None:
        return jsonify({'message': 'Product not found'}), 404
    return product_schema.jsonify(product)

# Create a product
@app.route('/products', methods=['POST'])
def create_product():
    """
    Add a new product to the inventory.
    """
    name = request.json['name']
    quantity = request.json['quantity']

    if not name or not quantity:
        return jsonify({'message': 'Name and quantity are required'}), 400

    new_product = {
        'id': str(uuid.uuid4()),
        'name': name,
        'quantity': quantity
    }
    products[new_product['id']] = new_product
    return product_schema.jsonify(new_product), 201

# Update a product
@app.route('/products/<id>', methods=['PUT'])
def update_product(id):
    """
    Update the details of an existing product.
    """
    product = products.get(id)
    if product is None:
        return jsonify({'message': 'Product not found'}), 404

    name = request.json.get('name', product['name'])
    quantity = request.json.get('quantity', product['quantity'])

    if not name or not quantity:
        return jsonify({'message': 'Name and quantity are required'}), 400

    product['name'] = name
    product['quantity'] = quantity
    return product_schema.jsonify(product)

# Delete a product
@app.route('/products/<id>', methods=['DELETE'])
def delete_product(id):
    """
    Remove a product from the inventory by its id.
    """
    if id not in products:
        return jsonify({'message': 'Product not found'}), 404

    del products[id]
    return '', 204

if __name__ == '__main__':
    app.run(debug=True)
