import cryptodome.cipher
import cryptodome.random

class Secure(ABC):
    def __init__(self, value, encryption_level):
        self.value = self.encrypt(value, encryption_level)
        self.encryption_level = encryption_level

    @abstractmethod
    def encrypt(self, value, encryption_level):
        pass

    @abstractmethod
    def decrypt(self, encrypted_value):
        pass

    def get_value(self, access_level):
        if access_level >= self.encryption_level:
            return self.decrypt(self.value)
        else:
            raise Exception("Access level is insufficient to decrypt the value.")

class SecureString(Secure, str):
    def encrypt(self, value, encryption_level):
        if isinstance(value, SecureString):
            return value.value
        key = cryptodome.random.get_random_bytes(16)
        cipher = cryptodome.cipher.AES.new(key, cryptodome.cipher.MODE_EAX)
        ciphertext, tag = cipher.encrypt_and_digest(value.encode('utf-8'))
        return cipher.nonce + tag + ciphertext

    def decrypt(self, encrypted_value):
        nonce, tag, ciphertext = encrypted_value[:16], encrypted_value[16:32], encrypted_value[32:]
        key = cryptodome.random.get_random_bytes(16)
        cipher = cryptodome.cipher.AES.new(key, cryptodome.cipher.MODE_EAX, nonce=nonce)
        return cipher.decrypt_and_verify(ciphertext, tag).decode('utf-8')

    def get_typed_value(self):
        return self.get_value(self.encryption_level)

class SecureDecimal(Secure, Decimal):
    def encrypt(self, value, encryption_level):
        if isinstance(value, SecureDecimal):
            return value.value
        key = cryptodome.random.get_random_bytes(16)
        cipher = cryptodome.cipher.AES.new(key, cryptodome.cipher.MODE_EAX)
        return cipher.nonce + cipher.encrypt(str(value))

    def decrypt(self, encrypted_value):
        nonce, ciphertext = encrypted_value[:16], encrypted_value[16:]
        key = cryptodome.random.get_random_bytes(16)
        cipher = cryptodome.cipher.AES.new(key, cryptodome.cipher.MODE_EAX, nonce=nonce)
        return Decimal(cipher.decrypt(ciphertext).decode('utf-8'))

    def get_typed_value(self):
        return self.decrypt(self.get_value(self.encryption_level))

class SecureDate(Secure, date):
    def encrypt(self, value, encryption_level):
        if isinstance(value, SecureDate):
            return value.value
        key = cryptodome.random.get_random_bytes(16)
        cipher = cryptodome.cipher.AES.new(key, cryptodome.cipher.MODE_EAX)
        return cipher.nonce + cipher.encrypt(str(value))

    def decrypt(self, encrypted_value):
        nonce, ciphertext = encrypted_value[:16], encrypted_value[16:]
        key = cryptodome.random.get_random_bytes(16)
        cipher = cryptodome.cipher.AES.new(key, cryptodome.cipher.MODE_EAX, nonce=nonce)
        return date.fromisoformat(cipher.decrypt(ciphertext).decode('utf-8'))

    def get_typed_value(self):
        return self.decrypt(self.get_value(self.encryption_level))

class SecureDateTime(Secure, datetime):
    def encrypt(self, value, encryption_level):
        if isinstance(value, SecureDateTime):
            return value.value
        key = cryptodome.random.get_random_bytes(16)
        cipher = cryptodome.cipher.AES.new(key, cryptodome.cipher.MODE_EAX)
        return cipher.nonce + cipher.encrypt(str(value))

    def decrypt(self, encrypted_value):
        nonce, ciphertext = encrypted_value[:16], encrypted_value[16:]
        key = cryptodome.random.get_random_bytes(16)
        cipher = cryptodome.cipher.AES.new(key, cryptodome.cipher.MODE_EAX, nonce=nonce)
        return datetime.fromisoformat(cipher.decrypt(ciphertext).decode('utf-8'))

    def get_typed_value(self):
        return self.decrypt(self.get_value(self.encryption_level))

class SecureIncompleteDate(Secure, Union[date, None]):
    def encrypt(self, value, encryption_level):
        if isinstance(value, SecureIncompleteDate):
            return value.value
        if value is None:
            return b''
        key = cryptodome.random.get_random_bytes(16)
        cipher = cryptodome.cipher.AES.new(key, cryptodome.cipher.MODE_EAX)
        return cipher.nonce + cipher.encrypt(str(value).encode('utf-8'))

    def decrypt(self, encrypted_value):
        if not encrypted_value:
