import os
import re
import xml.etree.ElementTree as ET
import shutil

# Define namespaces for EAD parsing
EAD_NS = {'arch': 'http://www.loc.gov/ead/ns/ead.xsd', 'did': 'http://www.loc.gov/ead/ns/did.xsd'}

# Function to parse EAD files and extract call numbers and collection IDs
def parse_ead_files(ead_dir):
    call_numbers = set()
    collection_ids = set()
    for filename in os.listdir(ead_dir):
        if filename.endswith('.xml'):
            ead_path = os.path.join(ead_dir, filename)
            tree = ET.parse(ead_path)
            root = tree.getroot()
            for did in root.findall('.//arch:did', EAD_NS):
                call_number = did.find('.//did:callNumber', EAD_NS).text
                collection_id = did.find('.//arch:unitid', EAD_NS).text
                call_numbers.add(call_number)
                collection_ids.add(collection_id)
    return call_numbers, collection_ids

# Function to parse MARC records and check for EAD link or call number
def parse_marc_records(marc_dir, call_numbers, collection_ids):
    ead_link_marc = []
    call_number_marc = []
    no_info_marc = []

    for filename in os.listdir(marc_dir):
        if filename.endswith('.xml'):
            marc_path = os.path.join(marc_dir, filename)
            try:
                tree = ET.parse(marc_path)
                root = tree.getroot()
                ead_link = False
                call_number = None
                for datafield in root.findall('.//datafield', namespaces={'marc': 'http://www.loc.gov/MARC21/slim'}):
                    if '856' in datafield.get('tag'):
                        ead_link = True
                        ead_url = datafield.find('subfield[@code="u"]', namespaces={'marc': 'http://www.loc.gov/MARC21/slim'}).text
                        collection_id = re.search(r'collection/(\w+)', ead_url).group(1)
                        if collection_id in collection_ids:
                            ead_link_marc.append(marc_path)
                    elif '852' in datafield.get('tag'):
                        call_number = datafield.find('subfield[@code="h"]', namespaces={'marc': 'http://www.loc.gov/MARC21/slim'}).text
                        if call_number in call_numbers:
                            call_number_marc.append(marc_path)
            except Exception as e:
                print(f"Error parsing MARC file {marc_path}: {e}")

    return ead_link_marc, call_number_marc, no_info_marc

# Main function to organize MARC records
def organize_marc_records(marc_dir, ead_dir):
    if not os.path.exists(marc_dir):
        print(f"Source directory {marc_dir} does not exist.")
        return

    if not os.path.exists(ead_dir):
        print(f"Source directory {ead_dir} does not exist.")
        return

    call_numbers, collection_ids = parse_ead_files(ead_dir)

    ead_link_marc, call_number_marc, no_info_marc = parse_marc_records(marc_dir, call_numbers, collection_ids)

    # Create output directories if they don't exist
    output_dirs = ['ead_link', 'call_number', 'no_info']
    for dir_name in output_dirs:
        if not os.path.exists(dir_name):
            os.makedirs(dir_name)

    # Copy files to appropriate directories
    for marc_file in ead_link_marc:
        shutil.copy(marc_file, 'ead_link')
    for marc_file in call_number_marc:
        shutil.copy(marc_file, 'call_number')
    for marc_file in no_info_marc:
        shutil.copy(marc_file, 'no_info')

# Example usage
organize_marc_records('path/to/marc/files', 'path/to/ead/files')
