```python
import re

def parse_transformations(file_path):
    with open(file_path, 'r') as file:
        content = file.read()

    pattern = r'(\d+)\s+([A-Z]),\s*(\d+)\s+([A-Z])\s*=>\s*(\d+)\s+([A-Z])'
    matches = re.findall(pattern, content)

    transformations = {}
    for match in matches:
        input_chemicals = {match[1]: int(match[2]), match[4]: int(match[5])}
        output_chemical = match[6]
        output_amount = int(match[3])

        if output_chemical not in transformations:
            transformations[output_chemical] = {'amount': 0, 'inputs': input_chemicals}
        else:
            transformations[output_chemical]['amount'] += output_amount
            for chemical, amount in input_chemicals.items():
                if chemical in transformations[output_chemical]['inputs']:
                    transformations[output_chemical]['inputs'][chemical] += amount
                else:
                    transformations[output_chemical]['inputs'][chemical] = amount

    return transformations

def calculate_fuel(transformations, ore_amount, target_chemical='FUEL'):
    ore_used = 0
    chemicals = {chemical: 0 for chemical in transformations}

    def calculate_fuel_for_chemical(chemical):
        nonlocal ore_used
        if chemical == target_chemical:
            return 0

        if chemical not in transformations:
            return float('inf')

        input_chemicals = transformations[chemical]['inputs']
        input_amounts = [chemicals[input_chemical] for input_chemical in input_chemicals]

        if sum(input_amounts) > ore_amount:
            return float('inf')

        new_amount = transformations[chemical]['amount']
        for input_chemical, amount in zip(input_chemicals, input_amounts):
            new_amount += calculate_fuel_for_chemical(input_chemical) * amount

        ore_used += new_amount * transformations[chemical]['inputs'][list(transformations[chemical]['inputs'].keys())[0]]
        return new_amount

    while True:
        max_fuel = max(calculate_fuel_for_chemical(chemical) for chemical in transformations)
        if max_fuel == float('inf'):
            break

        ore_amount -= max_fuel
        chemicals = {chemical: amount + max_fuel for chemical, amount in chemicals.items()}

    return ore_used, chemicals[target_chemical]

def find_max_fuel(transformations, ore_amount=1_000_000_000_000):
    low, high = 0, ore_amount
    while low < high:
        mid = (low + high + 1) // 2
        ore_used, fuel = calculate_fuel(transformations, mid)
        if ore_used <= ore_amount:
            low = mid
        else:
            high = mid - 1

    return low, calculate_fuel(transformations, low)[1]

if __name__ == "__main__":
    transformations = parse_transformations('transformations.txt')
    max_fuel, fuel_amount = find_max_fuel(transformations)
    print(f"Maximum FUEL that can be produced with {ore_amount} units of ORE: {fuel_amount}")
